function getFirebaseApp() {
  const existing = getApps().find(a => a.name === "production");
  return existing || initializeApp(FIREBASE_CONFIG, "production");
}

let productionFirebaseLoginPromise = null;

function signIntoProductionFirebaseBeforeReads() {
  if (!productionFirebaseLoginPromise) {
    const auth = getAuth(getFirebaseApp());
    productionFirebaseLoginPromise = signInWithEmailAndPassword(
      auth,
      import.meta.env.VITE_FIREBASE_LOGIN_EMAIL,
      import.meta.env.VITE_FIREBASE_LOGIN_PASSWORD
    ).then(() => undefined);
  }

  return productionFirebaseLoginPromise;
}

async function fetchReadyToShipCarts() {
  const db = getFirestore(getFirebaseApp());
  await signIntoProductionFirebaseBeforeReads();
  const q = query(collection(db, "carts"), where("status", "==", "ready_to_ship"));
  const snap = await getDocs(q);
  return snap.docs.map(d => ({ id: d.id, ...d.data() }));
}

// Firebase fetchers for production tab data
async function fetchActiveBuildsCarts() {
  const db = getFirestore(getFirebaseApp());
  await signIntoProductionFirebaseBeforeReads();
  const snap = await getDocs(collection(db, "carts"));
  const all = snap.docs.map(d => ({ id: d.id, ...d.data() }));
  // Active builds = only "built", "intake", and "incomplete" statuses
  return all.filter(c => c.status && ["built","intake","incomplete"].includes(c.status));
}

async function fetchInQCQueueCarts() {
  const db = getFirestore(getFirebaseApp());
  await signIntoProductionFirebaseBeforeReads();
  const q = query(collection(db, "carts"), where("status", "==", "in_queue"));
  const snap = await getDocs(q);
  return snap.docs.map(d => ({ id: d.id, ...d.data() }));
}

async function fetchQCPassedCarts() {
  const db = getFirestore(getFirebaseApp());
  await signIntoProductionFirebaseBeforeReads();
  const q = query(collection(db, "carts"), where("status", "==", "qc_pass"));
  const snap = await getDocs(q);
  return snap.docs.map(d => ({ id: d.id, ...d.data() }));
}

// ─── Color / model mapping ─────────────────────────────────────────────────────
const SHELL_TO_BODY = { "Red":"Red","White":"White","Blue":"Blue","Black":"Black","Burgundy":"Burgundy","Sky Blue":"Sky Blue","Matte Grey":"Matte Grey","Matte Gray":"Matte Grey","Silver":"Silver" };
const SEAT_MAP = { "Black":"Black","Brown":"Brown","Grey":"Grey","Gray":"Grey" };
const MODEL_NAME_MAP = { "The Golf":"Golf","THE GOLF":"Golf","the golf":"Golf","LIFTED 4":"Cruiser","Lifted 4":"Cruiser","lifted 4":"Cruiser","LIFTED4":"Cruiser","Lifted4":"Cruiser","lifted4":"Cruiser","LIFTED 6":"Limo","Lifted 6":"Limo","lifted 6":"Limo","LIFTED6":"Limo","Lifted6":"Limo","lifted6":"Limo","ECO 4":"ECO4","Eco 4":"ECO4","eco 4":"ECO4","ECO 6":"ECO6","Eco 6":"ECO6","eco 6":"ECO6","ECO2":"Golf","Eco2":"Golf","eco2":"Golf","ECO 2":"Golf","Eco 2":"Golf","eco 2":"Golf" };

const MODELS = ["Golf","ECO4","ECO6","Cruiser","Limo","F4","F4 LR"];
const BODY_COLORS = ["Red","White","Blue","Black","Burgundy","Sky Blue","Matte Grey","Silver"];
const SEAT_COLORS = ["Black","Brown","Grey"];
const PAGE_SIZE = 15;

function mapModelName(m) {
  if (!m) return m;
  if (MODELS.includes(m)) return m;
  if (MODEL_NAME_MAP[m]) return MODEL_NAME_MAP[m];
  const key = Object.keys(MODEL_NAME_MAP).find(k => k.toLowerCase() === m.toLowerCase());
  if (key) return MODEL_NAME_MAP[key];
  const direct = MODELS.find(cm => cm.toLowerCase() === m.toLowerCase());
  return direct || m;
}
function mapShellColor(c) {
  if (!c) return null;
  if (SHELL_TO_BODY[c]) return SHELL_TO_BODY[c];
  const key = Object.keys(SHELL_TO_BODY).find(k => k.toLowerCase() === c.toLowerCase());
  return key ? SHELL_TO_BODY[key] : null;
}
function mapSeatColor(c) {
  if (!c) return null;
  if (SEAT_MAP[c]) return SEAT_MAP[c];
  const key = Object.keys(SEAT_MAP).find(k => k.toLowerCase() === c.toLowerCase());
  return key ? SEAT_MAP[key] : null;
}

