const moneyNumber = v => { const n=Number(String(v??"").replace(/[^0-9.]/g,"")); return Number.isFinite(n)?n:0; };
const formatMoney = v => moneyNumber(v).toLocaleString("en-US",{style:"currency",currency:"USD"});
const makeOrderGroupId = () => `grp_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
let _lid = 1;
const ulid = () => ++_lid;
const daysSince = (dateStr) => {
  if (!dateStr) return null;
  return Math.floor((Date.now() - new Date(dateStr).getTime()) / 86400000);
};
const heatColor = (val, max) => {
  if (!max) return "#10b981";
  const t = Math.min(val / max, 1);
  if (t < 0.5) { const r=Math.round(16+(251-16)*t*2),g=Math.round(185+(191-185)*t*2),b=Math.round(129+(36-129)*t*2); return `rgb(${r},${g},${b})`; }
  const t2=(t-0.5)*2; const r=Math.round(251+(239-251)*t2),g=Math.round(191+(68-191)*t2),b=Math.round(36+(68-36)*t2);
  return `rgb(${r},${g},${b})`;
};
const exportCSV = (rows, filename) => {
  const blob = new Blob([rows.map(r=>r.map(c=>`"${String(c??'').replace(/"/g,'""')}"`).join(",")).join("\n")], {type:"text/csv;charset=utf-8;"});
  const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = filename; a.click();
};

