async function fetchParts() { const {data}=await sb.from("parts_inventory").select("*"); const m={}; (data||[]).forEach(r=>{m[r.part_key]=r.qty;}); return m; }
async function upsertPartQty(key,qty) { await sb.from("parts_inventory").upsert({part_key:key,qty},{onConflict:"part_key"}); }
async function fetchOrders() { const {data}=await sb.from("orders").select("*").order("created_at"); return (data||[]).map(dbToOrder); }
async function fetchFinished() { const {data,error}=await sb.from("finished_carts").select("*").order("created_at"); if(error) throw error; return (data||[]).map(dbToFinished); }
async function fetchReceiveLog() { const {data}=await sb.from("receive_log").select("*").order("created_at",{ascending:false}).limit(50); return data||[]; }

