const dbToOrder = r => ({
  id:r.id, orderGroupId:r.order_group_id||r.id, vinNew:r.vin_new, vinLegacy:r.vin_legacy,
  model:r.model, body:r.body, seat:r.seat, customer:r.customer,
  customization:r.customization, date:r.order_date, notes:r.notes,
  status:r.status, buildSource:r.build_source, finishedCartId:r.finished_cart_id,
  partsRestored:r.parts_restored||false,
  certSent:r.cert_sent, certSentDate:r.cert_sent_date,
  vehicleType:r.vehicle_type||"LSV", serialNumber:r.serial_number||"",
  shipQuote:r.ship_quote||false, paid:r.paid||false,
  estimateCreated:r.estimate_created||false, dealerDirectFinance:r.dealer_direct_finance||false,
  truckScheduled:r.truck_scheduled||false,
  shipDate:r.ship_date||"",
  orderAmount:r.order_amount ?? r.shipped_amount ?? "",
  shippedAmount:r.shipped_amount ?? r.order_amount ?? "",
  shippedAt:r.shipped_at || r.ship_date || "",
  orderQueuePosition:r.order_queue_position||0,
});
const orderToDB = (o, includePartsRestored=true) => {
  const base = {
    order_group_id:o.orderGroupId||o.id||null,
    vin_new:o.vinNew||"", vin_legacy:o.vinLegacy||"",
    model:o.model, body:o.body, seat:o.seat, customer:o.customer,
    customization:o.customization||"", order_date:o.date, notes:o.notes||"",
    status:o.status||"open", build_source:o.buildSource||null,
    finished_cart_id:o.finishedCartId||null,
    cert_sent:o.certSent||false, cert_sent_date:o.certSentDate||"",
    vehicle_type:o.vehicleType||"LSV", serial_number:o.serialNumber||"",
    ship_quote:o.shipQuote||false, paid:o.paid||false,
    estimate_created:o.estimateCreated||false, dealer_direct_finance:o.dealerDirectFinance||false,
    truck_scheduled:o.truckScheduled||false,
    ship_date:o.shipDate||"",
    order_amount:o.orderAmount===""||o.orderAmount==null?null:Number(o.orderAmount),
    shipped_amount:o.shippedAmount===""||o.shippedAmount==null?(o.orderAmount===""||o.orderAmount==null?null:Number(o.orderAmount)):Number(o.shippedAmount),
    shipped_at:o.shippedAt||o.shipDate||null,
    order_queue_position:o.orderQueuePosition||0,
  };
  if (includePartsRestored) base.parts_restored = o.partsRestored||false;
  return base;
};
const dbToFinished = r => ({
  id:r.id, orderGroupId:r.order_group_id||r.id, vinNew:r.vin_new, vinLegacy:r.vin_legacy,
  model:r.model, body:r.body, seat:r.seat, notes:r.notes,
  dateAdded:r.date_added, status:r.status, reservedFor:r.reserved_for,
});
const finishedToDB = c => ({
  vin_new:c.vinNew||"", vin_legacy:c.vinLegacy||"",
  model:c.model||"", body:c.body||"", seat:c.seat||"", notes:c.notes||"",
  date_added:c.dateAdded||today(),
  status:c.status||null, reserved_for:c.reservedFor||null,
});

// ─── UI primitives ────────────────────────────────────────────────────────────
function Btn({children,onClick,danger,small,style={},...rest}) {
  return <button onClick={onClick} {...rest} style={{padding:small?"5px 10px":"8px 16px",borderRadius:8,border:"none",cursor:"pointer",fontWeight:700,fontSize:small?12:13,background:danger?"#ef4444":"#2f7d57",color:"#fff",...style}}>{children}</button>;
}
function Sel({label,val,opts,onChange,wide}) {
  return (
    <label style={{display:"flex",flexDirection:"column",gap:3,flex:wide?"1 1 220px":"0 0 auto"}}>
      <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>{label}</span>
      <select value={val} onChange={e=>onChange(e.target.value)} style={{padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#f0f4f8"}}>
        {opts.map(o=><option key={o.v} value={o.v}>{o.l}</option>)}
      </select>
    </label>
  );
}
function Field({label,val,onChange,type="text"}) {
  return (
    <label style={{display:"flex",flexDirection:"column",gap:3}}>
      <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>{label}</span>
      <input type={type} value={val} onChange={e=>onChange(e.target.value)} style={{padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#ffffff"}}/>
    </label>
  );
}
function FPill({label,active,onClick,color="#6366f1"}) {
  return <button onClick={onClick} style={{padding:"5px 13px",borderRadius:20,border:`1.5px solid ${active?color:"#6b7280"}`,background:active?color:"#ffffff",color:active?"#fff":"#94a3b8",fontWeight:700,fontSize:12,cursor:"pointer",whiteSpace:"nowrap"}}>{label}</button>;
}
function ColorDot({color}) {
  const MAP={"Red":"#ef4444","White":"#e2e8f0","Blue":"#3b82f6","Black":"#1e293b","Burgundy":"#9f1239","Sky Blue":"#38bdf8","Matte Grey":"#94a3b8","Silver":"#cbd5e1"};
  if(!color||!MAP[color]) return null;
  return <span style={{display:"inline-block",width:10,height:10,borderRadius:"50%",background:MAP[color],border:"1px solid #dde3f0",marginRight:5,verticalAlign:"middle"}}/>;
}


function ExportIcon({size=14,color="currentColor"}) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M12 3v10m0 0l-3.5-3.5M12 13l3.5-3.5" stroke={color} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"/>
      <path d="M4 17v2a2 2 0 002 2h12a2 2 0 002-2v-2" stroke={color} strokeWidth="2.2" strokeLinecap="round"/>
    </svg>
  );
}

function ColorAvailWheel({count,maxCount,size=34}) {
  const pct = maxCount > 0 ? Math.min(count / maxCount, 1) : 0;
  const na = count === 0;
  const r = (size / 2) - 3;
  const circ = 2 * Math.PI * r;
  const dash = circ * pct;
  const color = na ? "#94a3b8" : pct >= 0.66 ? "#10b981" : pct >= 0.33 ? "#f59e0b" : "#ef4444";
  return (
    <div style={{position:"relative",width:size,height:size,flexShrink:0}} title={na ? "N/A" : `${count} of ${maxCount}`}>
      <svg width={size} height={size} style={{transform:"rotate(-90deg)"}}>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="#e2e8f0" strokeWidth={3}/>
        {!na && <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth={3} strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"/>}
      </svg>
      <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",fontSize:na?7:8,fontWeight:800,color:na?"#94a3b8":color}}>
        {na ? "N/A" : count}
      </div>
    </div>
  );
}


const isFinishedAvailable = c => !c.status || c.status === "available";
const sameModel = (a,b) => mapModelName(a||"") === mapModelName(b||"");
const sameBody = (a,b) => mapShellColor(a||"") === mapShellColor(b||"") || (a||"").toLowerCase() === (b||"").toLowerCase();
const sameSeat = (a,b) => mapSeatColor(a||"") === mapSeatColor(b||"") || (a||"").toLowerCase() === (b||"").toLowerCase();
const getAvailableFinishedCarts = (finished, model, body=null, seat=null) => (finished||[]).filter(c => {
  if (!isFinishedAvailable(c)) return false;
  if (model && !sameModel(c.model, model)) return false;
  if (body && body !== "TBD" && !sameBody(c.body, body)) return false;
  if (seat && seat !== "TBD" && !sameSeat(c.seat, seat)) return false;
  return true;
});

function FinishedBodyColorWheel({finished,model}) {
  const counts = BODY_COLORS.map(color => ({color,count:getAvailableFinishedCarts(finished,model,color,null).length}));
  const total = counts.reduce((sum,c)=>sum+c.count,0);
  const max = Math.max(1,...counts.map(c=>c.count));
  if (!model) return null;
  if (total === 0) {
    return (
      <div style={{display:"flex",alignItems:"center",gap:8,background:"#f1f5f9",border:"1px solid #cbd5e1",borderRadius:10,padding:"7px 10px",minHeight:38}}>
        <ColorAvailWheel count={0} maxCount={0}/>
        <div style={{fontSize:11,fontWeight:800,color:"#94a3b8",textTransform:"uppercase"}}>Finished Colors: N/A</div>
      </div>
    );
  }
  return (
    <div style={{display:"flex",alignItems:"center",gap:8,background:"#f8fafc",border:"1px solid #dde3f0",borderRadius:10,padding:"7px 10px",flexWrap:"wrap"}}>
      <span style={{fontSize:11,fontWeight:800,color:"#6b7280",textTransform:"uppercase",marginRight:2}}>Finished Colors</span>
      {counts.map(({color,count})=>(
        <div key={color} style={{display:"flex",alignItems:"center",gap:4,opacity:count?1:0.35}} title={`${color}: ${count}`}>
          <ColorDot color={color}/>
          <ColorAvailWheel count={count} maxCount={max} size={28}/>
        </div>
      ))}
    </div>
  );
}

// ─── Checkbox with ✓ / ✗ display ──────────────────────────────────────────────
function CheckField({label, checked, onChange, locked=false}) {
  return (
    <div style={{display:"flex",alignItems:"center",gap:8,cursor:locked?"default":"pointer"}} onClick={locked?undefined:()=>onChange(!checked)}>
      <div style={{width:22,height:22,borderRadius:5,border:`2px solid ${checked?"#10b981":"#ef4444"}`,background:checked?"#d1fae5":"#fee2e2",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,fontWeight:800,color:checked?"#065f46":"#991b1b",flexShrink:0}}>
        {checked?"✓":"✗"}
      </div>
      <span style={{fontSize:12,fontWeight:600,color:"#475569"}}>{label}</span>
    </div>
  );
}

// ─── VIN inputs ───────────────────────────────────────────────────────────────
function VinNewInput({value,mode,onValueChange,onModeChange,label="New VIN (Last 4)"}) {
  return (
    <label style={{display:"flex",flexDirection:"column",gap:3}}>
      <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>{label}</span>
      <div style={{display:"flex",gap:6,alignItems:"stretch"}}>
        <button type="button" onClick={()=>{const nm=mode==="na"?"typed":"na";onModeChange(nm);if(nm==="na")onValueChange("");}}
          style={{padding:"0 10px",borderRadius:7,border:`1.5px solid ${mode==="na"?"#6366f1":"#e2e8f0"}`,background:mode==="na"?"#6366f1":"#f8fafc",color:mode==="na"?"#fff":"#64748b",fontWeight:700,fontSize:11,cursor:"pointer",whiteSpace:"nowrap",flexShrink:0}}>
          {mode==="na"?"✓ N/A":"N/A"}
        </button>
        {mode!=="na"
          ? <input type="text" inputMode="numeric" placeholder="0000" maxLength={4} value={value} onChange={e=>{const v=e.target.value.replace(/\D/g,"").slice(0,4);onValueChange(v);}} style={{flex:1,padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",minWidth:0}}/>
          : <div style={{flex:1,padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",background:"#f1f5f9",fontSize:13,color:"#6b7280",fontStyle:"italic",display:"flex",alignItems:"center"}}>N/A</div>
        }
      </div>
    </label>
  );
}
function VinLegacyInput({value,onChange,label="Legacy VIN (Last 4)"}) {
  return (
    <label style={{display:"flex",flexDirection:"column",gap:3}}>
      <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>{label}</span>
      <input type="text" inputMode="numeric" placeholder="0000" maxLength={4} value={value} onChange={e=>{const v=e.target.value.replace(/\D/g,"").slice(0,4);onChange(v);}} style={{padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#ffffff"}}/>
    </label>
  );
}

