// ─── Receive Parts ─────────────────────────────────────────────────────────────
function expandBulkEntries(model,type,color,qty) {
  const bom=BOM[model]; if(!bom) return [];
  const entries=[];
  for(const {p,q} of bom){
    const pt=PARTS.find(x=>x.id===p);
    if(type==="body"&&(pt.body||p==="fp"||pt.cat==="Frame")) entries.push({partId:p,color:pt.body?color:"any",qty:q*qty});
    if(type==="seat"&&(pt.seat||pt.cat==="Battery")) entries.push({partId:p,color:pt.seat?color:"any",qty:q*qty});
  }
  return entries;
}

const MODEL_GROUPS=[
  {label:"All",models:[]},{label:"Golf",models:["Golf"]},{label:"ECO",models:["ECO4","ECO6"]},
  {label:"Lifted",models:["Cruiser","Limo"]},{label:"F4",models:["F4","F4 LR"]},
];
function groupToModels(filterLabel) {
  if(!filterLabel||filterLabel==="All") return MODELS;
  const grp=MODEL_GROUPS.find(g=>g.label===filterLabel);
  if(grp&&grp.models.length) return grp.models;
  if(MODELS.includes(filterLabel)) return [filterLabel];
  return MODELS;
}
function modelMatchesFilter(model,filterLabel) {
  if(!filterLabel||filterLabel==="All") return true;
  return groupToModels(filterLabel).includes(model);
}

function GroupedModelFilter({value,onChange,color="#6366f1"}) {
  const [openGroup,setOpenGroup]=useState(value==="All"?"All":MODEL_GROUPS.find(g=>g.models.includes(value))?.label||value);
  const handleGroupClick=(grp)=>{setOpenGroup(grp.label);if(!grp.models.length){onChange("All");return;}if(grp.models.length===1){onChange(grp.models[0]);return;}onChange(grp.models[0]);};
  const activeGroupObj=MODEL_GROUPS.find(g=>g.label===openGroup)||MODEL_GROUPS[0];
  const isGroupActive=(grp)=>{if(grp.label==="All"&&value==="All") return true;if(grp.models.length===1) return value===grp.models[0];return grp.models.includes(value);};
  return (
    <div style={{display:"flex",flexDirection:"column",gap:6}}>
      <div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}>
        <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase",whiteSpace:"nowrap"}}>Model:</span>
        {MODEL_GROUPS.map(grp=><FPill key={grp.label} label={grp.label} active={isGroupActive(grp)} onClick={()=>handleGroupClick(grp)} color={color}/>)}
      </div>
      {activeGroupObj.models.length>1&&(
        <div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center",paddingLeft:4}}>
          <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase",whiteSpace:"nowrap"}}>↳</span>
          {activeGroupObj.models.map(m=><FPill key={m} label={m} active={value===m} onClick={()=>onChange(m)} color="#a78bfa"/>)}
        </div>
      )}
    </div>
  );
}

function partsForModel(model) { if(!model) return PARTS; return PARTS.filter(p=>p.models[0]==="All"||p.models.includes(model)); }
const blankBulkLine=(model=MODELS[0])=>({id:ulid(),model,type:"body",color:BODY_COLORS[0],qty:1});

function WeeklyReceiveHistory({receiveLog,expandedLogs,toggleLog,fmtTs}) {
  const [expandedWeeks,setExpandedWeeks]=useState(new Set());
  const toggleWeek=k=>setExpandedWeeks(prev=>{const n=new Set(prev);n.has(k)?n.delete(k):n.add(k);return n;});
  const weekMap={};
  receiveLog.forEach(log=>{const {key,sun,sat}=getWeekKey(log.created_at||new Date().toISOString());if(!weekMap[key]) weekMap[key]={sun,sat,key,logs:[]};weekMap[key].logs.push(log);});
  const weeks=Object.values(weekMap).sort((a,b)=>b.key.localeCompare(a.key));
  return (
    <div style={{display:"flex",flexDirection:"column",gap:10}}>
      {weeks.map(week=>{
        const isWeekOpen=expandedWeeks.has(week.key);
        const totalLines=week.logs.reduce((s,l)=>s+l.entries.length,0);
        return (
          <div key={week.key} style={{borderRadius:10,overflow:"hidden",border:"1px solid #ddd6fe"}}>
            <div onClick={()=>toggleWeek(week.key)} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 14px",cursor:"pointer",background:isWeekOpen?"#ede9fe":"#f5f3ff"}}>
              <div style={{fontWeight:700,fontSize:13,color:"#6d28d9"}}>{fmtWeekLabel(week.sun,week.sat)}</div>
              <div style={{display:"flex",alignItems:"center",gap:10}}>
                <span style={{fontSize:11,color:"#7c3aed"}}>{week.logs.length} receipt{week.logs.length!==1?"s":""} · {totalLines} line{totalLines!==1?"s":""}</span>
                <span style={{fontSize:11,fontWeight:700,color:"#7c3aed"}}>{isWeekOpen?"▲":"▼"}</span>
              </div>
            </div>
            {isWeekOpen&&(
              <div style={{background:"#fff",borderTop:"1px solid #ddd6fe",display:"flex",flexDirection:"column",gap:6,padding:"8px 10px"}}>
                {week.logs.map(log=>{
                  const isOpen=expandedLogs.has(log.id);
                  return (
                    <div key={log.id} style={{borderLeft:"3px solid #6366f1",borderRadius:"0 8px 8px 0",overflow:"hidden"}}>
                      <div onClick={()=>toggleLog(log.id)} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 12px",cursor:"pointer",background:isOpen?"#f5f3ff":"#f8fafc"}}>
                        <div style={{fontSize:12,color:"#6366f1",fontWeight:700}}>{fmtTs(log.created_at)}</div>
                        <div style={{display:"flex",alignItems:"center",gap:10}}><span style={{fontSize:11,color:"#6b7280"}}>{log.entries.length} line{log.entries.length!==1?"s":""}</span><span style={{fontSize:11,fontWeight:700,color:"#6366f1"}}>{isOpen?"▲":"▼"}</span></div>
                      </div>
                      {isOpen&&(
                        <div style={{padding:"8px 14px 12px",background:"#ffffff",borderTop:"1px solid #2e1f5e"}}>
                          {log.entries.map((e,i)=>{const pt=PARTS.find(p=>p.id===e.partId);return<div key={i} style={{fontSize:13,color:"#6b7280",padding:"3px 0"}}><span style={{fontWeight:700,color:"#10b981"}}>+{e.qty}</span> {pt?.name}{e.color!=="any"&&<> — <span style={{color:"#6366f1"}}>{e.color}</span></>}<span style={{color:"#6b7280",fontSize:11,marginLeft:6}}>({pt?.models[0]==="All"?"All models":pt?.models.join(", ")})</span></div>;})}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function ReceiveTab({receiveParts,receiveLog}) {
  const [mode,setMode]=useState("granular");
  const [granularGroup,setGranularGroup]=useState("All");
  const [granularSubModel,setGranularSubModel]=useState(null);
  const granularEffectiveModel=useMemo(()=>{const grp=MODEL_GROUPS.find(g=>g.label===granularGroup);if(!grp||!grp.models.length) return null;if(grp.models.length===1) return grp.models[0];return granularSubModel||grp.models[0];},[granularGroup,granularSubModel]);
  const getFilteredParts=(effectiveModel)=>{if(!effectiveModel) return PARTS;return partsForModel(effectiveModel);};
  const blankLine=(effectiveModel=null)=>{const fp=getFilteredParts(effectiveModel);const pid=fp.length>0?fp[0].id:PARTS[0].id;const pt=PARTS.find(p=>p.id===pid);return {id:ulid(),partId:pid,color:pt.body?BODY_COLORS[0]:pt.seat?SEAT_COLORS[0]:"any",qty:1};};
  const [lines,setLines]=useState([blankLine()]);
  const [bulkGroup,setBulkGroup]=useState("All");
  const [bulkSubModel,setBulkSubModel]=useState(null);
  const [bulkLines,setBulkLines]=useState([blankBulkLine()]);
  const [previewId,setPreviewId]=useState(null);
  const bulkEffectiveModel=useMemo(()=>{const grp=MODEL_GROUPS.find(g=>g.label===bulkGroup);if(!grp||!grp.models.length) return null;if(grp.models.length===1) return grp.models[0];return bulkSubModel||grp.models[0];},[bulkGroup,bulkSubModel]);
  const bulkVisibleModels=useMemo(()=>{if(!bulkEffectiveModel) return MODELS;return [bulkEffectiveModel];},[bulkEffectiveModel]);
  const [expandedLogs,setExpandedLogs]=useState(new Set());
  const toggleLog=id=>setExpandedLogs(prev=>{const n=new Set(prev);n.has(id)?n.delete(id):n.add(id);return n;});
  const setPart=(lid,partId)=>setLines(prev=>prev.map(l=>{if(l.id!==lid) return l;const pt=PARTS.find(p=>p.id===partId);return {...l,partId,color:pt.body?BODY_COLORS[0]:pt.seat?SEAT_COLORS[0]:"any"};}));
  const changeGranularGroup=(grpLabel)=>{const grp=MODEL_GROUPS.find(g=>g.label===grpLabel);setGranularGroup(grpLabel);const newSub=grp&&grp.models.length>1?grp.models[0]:null;setGranularSubModel(newSub);const effModel=grp&&grp.models.length?grp.models[0]:null;const fp=getFilteredParts(effModel);const pid=fp.length>0?fp[0].id:PARTS[0].id;const pt=PARTS.find(p=>p.id===pid);setLines([{id:ulid(),partId:pid,color:pt.body?BODY_COLORS[0]:pt.seat?SEAT_COLORS[0]:"any",qty:1}]);};
  const changeGranularSubModel=(sub)=>{setGranularSubModel(sub);const fp=partsForModel(sub);const pid=fp.length>0?fp[0].id:PARTS[0].id;const pt=PARTS.find(p=>p.id===pid);setLines([{id:ulid(),partId:pid,color:pt.body?BODY_COLORS[0]:pt.seat?SEAT_COLORS[0]:"any",qty:1}]);};
  const changeBulkGroup=(grpLabel)=>{const grp=MODEL_GROUPS.find(g=>g.label===grpLabel);setBulkGroup(grpLabel);setBulkSubModel(null);const effModel=grp?.bulkModel||(grp&&grp.models.length?grp.models[0]:null);setBulkLines([blankBulkLine(effModel||MODELS[0])]);setPreviewId(null);};
  const changeBulkSubModel=(sub)=>{setBulkSubModel(sub);setBulkLines([blankBulkLine(sub)]);setPreviewId(null);};
  const submitGranular=()=>{receiveParts(lines.map(l=>({partId:l.partId,color:l.color,qty:l.qty})));setLines([blankLine(granularEffectiveModel)]);};
  const setBulkLF=(lid,field,val)=>setBulkLines(prev=>prev.map(l=>{if(l.id!==lid) return l;const updated={...l,[field]:val};if(field==="type") updated.color=val==="body"?BODY_COLORS[0]:SEAT_COLORS[0];return updated;}));
  const submitBulk=()=>{const visibleLines=bulkLines.filter(l=>bulkVisibleModels.includes(l.model));const allEntries=[];for(const l of visibleLines) allEntries.push(...expandBulkEntries(l.model,l.type,l.color,l.qty));const merged={};for(const e of allEntries){const k=`${e.partId}::${e.color}`;merged[k]={partId:e.partId,color:e.color,qty:(merged[k]?.qty||0)+e.qty};}receiveParts(Object.values(merged));setBulkLines([blankBulkLine(bulkVisibleModels[0]||MODELS[0])]);setPreviewId(null);};
  const fmtTs=ts=>{if(!ts) return "—";try{const d=new Date(ts);return d.toLocaleDateString("en-US",{month:"2-digit",day:"2-digit",year:"numeric"})+" "+d.toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"});}catch{return ts;}};
  const activeGranularGrp=MODEL_GROUPS.find(g=>g.label===granularGroup);
  const activeBulkGrp=MODEL_GROUPS.find(g=>g.label===bulkGroup);

  return (
    <div>
      <div style={{display:"flex",gap:0,marginBottom:18,background:"#f0f4f8",borderRadius:12,padding:5,boxShadow:"0 1px 8px rgba(10,53,132,0.1)",width:"fit-content"}}>
        <button onClick={()=>setMode("granular")} style={{padding:"8px 20px",borderRadius:8,border:"none",cursor:"pointer",fontWeight:700,fontSize:13,background:mode==="granular"?"#6366f1":"transparent",color:mode==="granular"?"#fff":"#64748b"}}>🔩 By Individual Part</button>
        <button onClick={()=>setMode("bulk")} style={{padding:"8px 20px",borderRadius:8,border:"none",cursor:"pointer",fontWeight:700,fontSize:13,background:mode==="bulk"?"#6366f1":"transparent",color:mode==="bulk"?"#fff":"#64748b"}}>📦 By Body / Seat Group</button>
      </div>

      {mode==="granular"&&(
        <div style={{background:"#ffffff",borderRadius:14,padding:20,marginBottom:20,boxShadow:"0 1px 8px rgba(10,53,132,0.1)"}}>
          <div style={{fontWeight:700,fontSize:15,color:"#0a3584",marginBottom:4}}>📥 Receive by Individual Part</div>
          <div style={{fontSize:12,color:"#6b7280",marginBottom:12}}>Use for frames, batteries, and any specific individual parts.</div>
          <div style={{display:"flex",gap:8,marginBottom:activeGranularGrp&&activeGranularGrp.models.length>1?8:14,flexWrap:"wrap",alignItems:"center"}}>
            <span style={{fontSize:12,fontWeight:700,color:"#6b7280",whiteSpace:"nowrap"}}>Filter by model:</span>
            {MODEL_GROUPS.map(grp=><FPill key={grp.label} label={grp.label} active={granularGroup===grp.label} onClick={()=>changeGranularGroup(grp.label)}/>)}
          </div>
          {activeGranularGrp&&activeGranularGrp.models.length>1&&(
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,padding:"10px 14px",background:"#f5f3ff",borderRadius:10,border:"1px solid #2e1f5e"}}>
              <span style={{fontSize:12,fontWeight:700,color:"#7c3aed"}}>Select model:</span>
              {activeGranularGrp.models.map(m=><FPill key={m} label={m} active={(granularSubModel||activeGranularGrp.models[0])===m} onClick={()=>changeGranularSubModel(m)} color="#7c3aed"/>)}
            </div>
          )}
          <div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>
            {lines.map((l,i)=>{
              const filteredParts=getFilteredParts(granularEffectiveModel);
              const pt=PARTS.find(p=>p.id===l.partId)||filteredParts[0];
              const colorOpts=pt&&pt.body?BODY_COLORS:pt&&pt.seat?SEAT_COLORS:null;
              return (
                <div key={l.id} style={{display:"flex",gap:10,alignItems:"flex-end",flexWrap:"wrap",background:i%2===0?"#f8fafc":"#fff",borderRadius:10,padding:"10px 12px",border:"1px solid #dde3f0"}}>
                  <Sel label="Part" val={l.partId} opts={filteredParts.map(p=>({v:p.id,l:`${p.name} — ${p.models[0]==="All"?"All models":p.models.join(", ")}`}))} onChange={v=>setPart(l.id,v)} wide/>
                  {colorOpts&&<Sel label={pt.body?"Body Color":"Seat Color"} val={l.color} opts={colorOpts.map(c=>({v:c,l:c}))} onChange={v=>setLines(prev=>prev.map(x=>x.id===l.id?{...x,color:v}:x))}/>}
                  <label style={{display:"flex",flexDirection:"column",gap:3}}><span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Qty</span><input type="number" min={1} value={l.qty} onChange={e=>setLines(prev=>prev.map(x=>x.id===l.id?{...x,qty:Math.max(1,+e.target.value)}:x))} style={{width:72,padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13}}/></label>
                  <div style={{display:"flex",flexDirection:"column",gap:3}}><span style={{fontSize:11,color:"transparent"}}>x</span><Btn small danger onClick={()=>setLines(prev=>prev.length>1?prev.filter(x=>x.id!==l.id):prev)}>✕</Btn></div>
                  {pt&&<div style={{fontSize:11,color:"#6b7280",alignSelf:"center"}}>→ {pt.models[0]==="All"?"All models":pt.models.join(", ")}</div>}
                </div>
              );
            })}
          </div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
            <Btn onClick={()=>setLines(prev=>[...prev,blankLine(granularEffectiveModel)])} style={{background:"#dde3f0",color:"#6b7280"}}>+ Add Line</Btn>
            <Btn onClick={submitGranular}>✓ Receive All Lines</Btn>
          </div>
        </div>
      )}

      {mode==="bulk"&&(
        <div style={{display:"flex",gap:16,alignItems:"flex-start",flexWrap:"wrap"}}>
          <div style={{flex:"1 1 0",background:"#ffffff",borderRadius:14,padding:20,marginBottom:20,boxShadow:"0 1px 8px rgba(10,53,132,0.1)",minWidth:320}}>
          <div style={{fontWeight:700,fontSize:15,color:"#0a3584",marginBottom:4}}>📦 Receive by Body / Seat Group</div>
          <div style={{fontSize:12,color:"#6b7280",marginBottom:12}}>Enter how many body color sets or seat color sets arrived for a model.</div>
          <div style={{display:"flex",gap:8,marginBottom:activeBulkGrp&&activeBulkGrp.models.length>1&&!activeBulkGrp.bulkModel?8:14,flexWrap:"wrap",alignItems:"center"}}>
            <span style={{fontSize:12,fontWeight:700,color:"#6b7280",whiteSpace:"nowrap"}}>Filter by model:</span>
            {MODEL_GROUPS.map(grp=><FPill key={grp.label} label={grp.bulkLabel||grp.label} active={bulkGroup===grp.label} onClick={()=>changeBulkGroup(grp.label)}/>)}
          </div>
          {activeBulkGrp&&activeBulkGrp.models.length>1&&!activeBulkGrp.bulkModel&&(
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,padding:"10px 14px",background:"#f5f3ff",borderRadius:10,border:"1px solid #2e1f5e"}}>
              <span style={{fontSize:12,fontWeight:700,color:"#7c3aed"}}>Select model:</span>
              {activeBulkGrp.models.map(m=><FPill key={m} label={m} active={(bulkSubModel||activeBulkGrp.models[0])===m} onClick={()=>changeBulkSubModel(m)} color="#7c3aed"/>)}
            </div>
          )}
          <div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>
            {bulkLines.map((l,i)=>{
              if(!bulkVisibleModels.includes(l.model)) return null;
              const colorOpts=l.type==="body"?BODY_COLORS:SEAT_COLORS;
              const preview=expandBulkEntries(l.model,l.type,l.color,l.qty);
              const isExpanded=previewId===l.id;
              return (
                <div key={l.id} style={{borderRadius:12,border:"1px solid #dde3f0",overflow:"hidden"}}>
                  <div style={{display:"flex",gap:10,alignItems:"flex-end",flexWrap:"wrap",background:i%2===0?"#f8fafc":"#fff",padding:"12px 14px"}}>
                    <Sel label="Model" val={l.model} opts={bulkVisibleModels.map(m=>({v:m,l:m}))} onChange={v=>setBulkLF(l.id,"model",v)}/>
                    <div style={{display:"flex",flexDirection:"column",gap:3}}><span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Type</span><div style={{display:"flex",gap:0,borderRadius:8,overflow:"hidden",border:"1px solid #dde3f0"}}>{["body","seat"].map(t=><button key={t} onClick={()=>setBulkLF(l.id,"type",t)} style={{padding:"7px 14px",border:"none",cursor:"pointer",fontWeight:700,fontSize:12,background:l.type===t?(t==="body"?"#3b82f6":"#8b5cf6"):"#fff",color:l.type===t?"#fff":"#64748b"}}>{t==="body"?"🎨 Body":"🪑 Seat"}</button>)}</div></div>
                    <Sel label={l.type==="body"?"Body Color":"Seat Color"} val={l.color} opts={colorOpts.map(c=>({v:c,l:c}))} onChange={v=>setBulkLF(l.id,"color",v)}/>
                    <label style={{display:"flex",flexDirection:"column",gap:3}}><span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Qty</span><input type="number" min={1} value={l.qty} onChange={e=>setBulkLF(l.id,"qty",Math.max(1,+e.target.value))} style={{width:72,padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13}}/></label>
                    <div style={{display:"flex",gap:6,alignSelf:"flex-end"}}>
                      <button onClick={()=>setPreviewId(isExpanded?null:l.id)} style={{padding:"7px 12px",borderRadius:8,border:"1px solid #dde3f0",background:isExpanded?"#eff6ff":"#f8fafc",cursor:"pointer",fontSize:11,fontWeight:700,color:isExpanded?"#3b82f6":"#64748b"}}>{isExpanded?"▲ Hide":"▼ Preview"}</button>
                      <Btn small danger onClick={()=>setBulkLines(prev=>prev.length>1?prev.filter(x=>x.id!==l.id):prev)}>✕</Btn>
                    </div>
                  </div>
                  {isExpanded&&(
                    <div style={{background:l.type==="body"?"#eff6ff":"#f5f3ff",borderTop:`1px solid ${l.type==="body"?"#bae6fd":"#ddd6fe"}`,padding:"10px 14px"}}>
                      <div style={{fontSize:12,fontWeight:700,color:l.type==="body"?"#1d4ed8":"#7c3aed",marginBottom:8}}>Parts added for {l.qty} × {l.model} {l.type==="body"?`${l.color} body`:`${l.color} seat`}:</div>
                      <div style={{display:"flex",flexWrap:"wrap",gap:6}}>{preview.map((e,pi)=>{const pt=PARTS.find(p=>p.id===e.partId);return<div key={pi} style={{background:"#ffffff",borderRadius:7,padding:"5px 11px",border:`1px solid ${l.type==="body"?"#bae6fd":"#ddd6fe"}`,fontSize:12,color:"#0a3584"}}><span style={{fontWeight:700,color:"#10b981"}}>+{e.qty}</span> {pt?.name}<span style={{color:l.type==="body"?"#3b82f6":"#8b5cf6",marginLeft:4,fontWeight:600}}>{e.color}</span></div>;})}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
            <Btn onClick={()=>setBulkLines(prev=>[...prev,blankBulkLine(bulkVisibleModels[0]||MODELS[0])])} style={{background:"#dde3f0",color:"#6b7280"}}>+ Add Another Line</Btn>
            <Btn onClick={submitBulk}>✓ Receive All</Btn>
          </div>
        </div>
        <ReceiveByCartPanel receiveParts={receiveParts} bulkVisibleModels={bulkVisibleModels}/>
      </div>
      )}

      {receiveLog.length>0&&(
        <div style={{background:"#ffffff",borderRadius:14,padding:18,boxShadow:"0 1px 8px rgba(10,53,132,0.1)"}}>
          <div style={{fontWeight:700,fontSize:14,color:"#0a3584",marginBottom:14}}>📜 Receive History</div>
          <WeeklyReceiveHistory receiveLog={receiveLog} expandedLogs={expandedLogs} toggleLog={toggleLog} fmtTs={fmtTs}/>
        </div>
      )}
    </div>
  );
}


function ReceiveByCartPanel({receiveParts,bulkVisibleModels}) {
  const availableModels = bulkVisibleModels && bulkVisibleModels.length ? bulkVisibleModels : MODELS;
  const [model,setModel] = useState(availableModels[0] || MODELS[0]);
  const [bodyColor,setBodyColor] = useState(BODY_COLORS[0]);
  const [seatColor,setSeatColor] = useState(SEAT_COLORS[0]);
  const [qty,setQty] = useState(1);
  const [previewOpen,setPreviewOpen] = useState(false);

  useEffect(()=>{
    if(!availableModels.includes(model)) setModel(availableModels[0] || MODELS[0]);
  },[availableModels.join("|"),model]);

  const preview = useMemo(()=>{
    const bom = BOM[model] || [];
    return bom.map(({p,q})=>{
      const pt = PARTS.find(x=>x.id===p);
      const color = pt?.body ? bodyColor : pt?.seat ? seatColor : "any";
      return {partId:p,color,qty:q*qty,partName:pt?.name||p};
    });
  },[model,bodyColor,seatColor,qty]);

  const handleReceive = () => {
    receiveParts(preview.map(({partId,color,qty})=>({partId,color,qty})));
    setPreviewOpen(false);
  };

  return (
    <div style={{flex:"1 1 0",background:"#ffffff",borderRadius:14,padding:20,marginBottom:20,boxShadow:"0 1px 8px rgba(10,53,132,0.1)",minWidth:280}}>
      <div style={{fontWeight:700,fontSize:15,color:"#0a3584",marginBottom:4}}>🛒 Receive by Cart</div>
      <div style={{fontSize:12,color:"#6b7280",marginBottom:14}}>Select a full cart spec to receive all required body, seat, battery, frame, and panel parts together.</div>
      <div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>
        <Sel label="Model" val={model} opts={availableModels.map(m=>({v:m,l:m}))} onChange={setModel}/>
        <Sel label="Body Color" val={bodyColor} opts={BODY_COLORS.map(c=>({v:c,l:c}))} onChange={setBodyColor}/>
        <Sel label="Seat Color" val={seatColor} opts={SEAT_COLORS.map(c=>({v:c,l:c}))} onChange={setSeatColor}/>
        <label style={{display:"flex",flexDirection:"column",gap:3}}>
          <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Qty of Carts</span>
          <input type="number" min={1} value={qty} onChange={e=>setQty(Math.max(1,+e.target.value||1))} style={{width:80,padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13}}/>
        </label>
      </div>
      <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:previewOpen?10:14}}>
        <button onClick={()=>setPreviewOpen(v=>!v)} style={{padding:"7px 12px",borderRadius:8,border:"1px solid #dde3f0",background:previewOpen?"#f0fdf4":"#f8fafc",cursor:"pointer",fontSize:11,fontWeight:700,color:previewOpen?"#10b981":"#64748b"}}>{previewOpen?"▲ Hide":"▼ Preview"}</button>
      </div>
      {previewOpen&&(
        <div style={{background:"#f0fdf4",borderRadius:10,padding:"10px 13px",marginBottom:14,border:"1px solid #86efac"}}>
          <div style={{fontSize:11,fontWeight:700,color:"#065f46",marginBottom:8,textTransform:"uppercase"}}>Parts that will be added:</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
            {preview.map((e,i)=>(
              <div key={i} style={{background:"#fff",borderRadius:6,padding:"3px 9px",fontSize:11,color:"#0a3584",border:"1px solid #86efac"}}>
                <span style={{fontWeight:700,color:"#10b981"}}>+{e.qty}</span> {e.partName}
                {e.color!=="any"&&<span style={{color:"#6366f1",marginLeft:4}}>{e.color}</span>}
              </div>
            ))}
          </div>
        </div>
      )}
      <Btn onClick={handleReceive}>✓ Receive Cart Parts</Btn>
    </div>
  );
}

// ─── Parts Inventory ───────────────────────────────────────────────────────────
function PartsTab({parts,onAdjust,onBulkSave}) {
  const [filterCat,setFilterCat]=useState("All");
  const [filterModel,setFilterModel]=useState("All");
  const [colorFilters,setColorFilters]=useState({});
  const [editKey,setEditKey]=useState(null);
  const [editVal,setEditVal]=useState("");
  const [bulkMode,setBulkMode]=useState(false);
  const [bulkEdits,setBulkEdits]=useState({});
  const [saving,setSaving]=useState(false);
  const cats=["All",...[...new Set(PARTS.map(p=>p.cat))]];
  const filteredParts=PARTS.filter(p=>{if(filterCat!=="All"&&p.cat!==filterCat) return false;if(filterModel!=="All"){const targets=groupToModels(filterModel);return p.models[0]==="All"||p.models.some(m=>targets.includes(m));}return true;});
  const getPartQty=(part,colorFilter)=>{if(part.body){if(colorFilter&&colorFilter!=="All") return parts[psk(part.id,colorFilter)]||0;return BODY_COLORS.reduce((s,c)=>s+(parts[psk(part.id,c)]||0),0);}if(part.seat){if(colorFilter&&colorFilter!=="All") return parts[psk(part.id,colorFilter)]||0;return SEAT_COLORS.reduce((s,c)=>s+(parts[psk(part.id,c)]||0),0);}return parts[psk(part.id,"any")]||0;};
  const getEditKey=(part,colorFilter)=>{if(part.body){if(colorFilter&&colorFilter!=="All") return psk(part.id,colorFilter);return null;}if(part.seat){if(colorFilter&&colorFilter!=="All") return psk(part.id,colorFilter);return null;}return psk(part.id,"any");};
  const startEdit=(part,colorFilter)=>{const key=getEditKey(part,colorFilter);if(!key) return;setEditKey(key);setEditVal(String(parts[key]||0));};
  const saveEdit=async(part,colorFilter)=>{const key=getEditKey(part,colorFilter);if(!key) return;const q=Math.max(0,parseInt(editVal)||0);await onAdjust(key,q);setEditKey(null);};
  const enterBulk=()=>{const init={};filteredParts.forEach(part=>{if(part.body) BODY_COLORS.forEach(c=>{const k=psk(part.id,c);init[k]=String(parts[k]||0);});else if(part.seat) SEAT_COLORS.forEach(c=>{const k=psk(part.id,c);init[k]=String(parts[k]||0);});else{const k=psk(part.id,"any");init[k]=String(parts[k]||0);}});setBulkEdits(init);setBulkMode(true);};
  const saveBulk=async()=>{setSaving(true);const updates=Object.entries(bulkEdits).map(([key,val])=>({key,qty:Math.max(0,parseInt(val)||0)}));await onBulkSave(updates);setBulkMode(false);setSaving(false);};
  const setColorFilter=(partId,color)=>setColorFilters(prev=>({...prev,[partId]:color}));
  return (
    <div>
      <div style={{background:"#fffbeb",border:"1px solid #78350f",borderRadius:10,padding:"10px 14px",marginBottom:14,fontSize:13,color:"#92400e"}}>💡 <strong>Tip:</strong> Select a specific color to view or edit that color's quantity.</div>
      <div style={{display:"flex",gap:8,marginBottom:10,flexWrap:"wrap",alignItems:"center"}}>
        {cats.map(c=><FPill key={c} label={c} active={filterCat===c} onClick={()=>setFilterCat(c)}/>)}
        <div style={{marginLeft:"auto",display:"flex",gap:8}}>
          {!bulkMode?<Btn onClick={enterBulk} style={{background:"#0ea5e9",color:"#fff"}}>✏️ Bulk Edit</Btn>:<><Btn onClick={saveBulk} style={{background:"#10b981"}}>{saving?"Saving…":"💾 Save All"}</Btn><Btn onClick={()=>{setBulkMode(false);setBulkEdits({});}} style={{background:"#dde3f0",color:"#6b7280"}}>Cancel</Btn></>}
        </div>
      </div>
      <div style={{marginBottom:14}}><GroupedModelFilter value={filterModel} onChange={setFilterModel} color="#0ea5e9"/></div>
      <div style={{background:"#ffffff",borderRadius:12,overflow:"auto",boxShadow:"0 1px 6px rgba(10,53,132,0.08)"}}>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
          <thead><tr style={{background:"#f0f4fb"}}>{["Part","Models","Color Filter","On Hand"].map(h=><th key={h} style={{padding:"10px 14px",textAlign:"left",color:"#6b7280",fontWeight:700,borderBottom:"2px solid #dde3f0"}}>{h}</th>)}</tr></thead>
          <tbody>
            {filteredParts.map((part,i)=>{
              const colorFilter=colorFilters[part.id]||"All";
              const displayQty=getPartQty(part,colorFilter);
              const editableKey=getEditKey(part,colorFilter);
              const colorOpts=part.body?["All",...BODY_COLORS]:part.seat?["All",...SEAT_COLORS]:null;
              const isEditing=editKey===editableKey&&editableKey!==null;
              if(bulkMode){
                const colorList=part.body?BODY_COLORS:part.seat?SEAT_COLORS:null;
                return <tr key={part.id} style={{background:i%2===0?"#fff":"#f8fafc",verticalAlign:"top"}}><td style={{padding:"10px 14px",fontWeight:600,color:"#0a3584"}}>{part.name}</td><td style={{padding:"10px 14px",fontSize:12,color:"#6b7280"}}>{part.models[0]==="All"?"All models":part.models.join(", ")}</td><td colSpan={2} style={{padding:"10px 14px"}}>{colorList?<div style={{display:"flex",flexWrap:"wrap",gap:8}}>{colorList.map(c=>{const k=psk(part.id,c);return<div key={c} style={{display:"flex",flexDirection:"column",gap:3,alignItems:"center"}}>{part.body&&<ColorDot color={c}/>}<span style={{fontSize:11,color:"#6b7280",fontWeight:600,whiteSpace:"nowrap"}}>{c}</span><input type="number" min={0} value={bulkEdits[k]??String(parts[k]||0)} onChange={e=>setBulkEdits(prev=>({...prev,[k]:e.target.value}))} style={{width:64,padding:"4px 8px",borderRadius:6,border:"2px solid #0ea5e9",fontSize:13,fontWeight:700,color:"#0a3584",background:"#fff",textAlign:"center"}}/></div>;})}:</div>:<input type="number" min={0} value={bulkEdits[psk(part.id,"any")]??String(parts[psk(part.id,"any")]||0)} onChange={e=>setBulkEdits(prev=>({...prev,[psk(part.id,"any")]:e.target.value}))} style={{width:80,padding:"4px 8px",borderRadius:6,border:"2px solid #0ea5e9",fontSize:13,fontWeight:700,color:"#0a3584",background:"#fff"}}/>}</td></tr>;
              }
              return <tr key={part.id} style={{background:i%2===0?"#fff":"#f8fafc"}}><td style={{padding:"8px 14px",fontWeight:600,color:"#0a3584"}}>{part.name}</td><td style={{padding:"8px 14px",fontSize:12,color:"#6b7280"}}>{part.models[0]==="All"?"All models":part.models.join(", ")}</td><td style={{padding:"8px 14px"}}>{colorOpts?<select value={colorFilter} onChange={e=>setColorFilter(part.id,e.target.value)} style={{padding:"5px 9px",borderRadius:7,border:"1px solid #dde3f0",fontSize:12,color:"#0a3584",background:"#f8fafc",cursor:"pointer"}}>{colorOpts.map(c=><option key={c} value={c}>{c==="All"?"All colors":c}</option>)}</select>:<span style={{color:"#6b7280",fontStyle:"italic",fontSize:12}}>Universal</span>}</td><td style={{padding:"8px 14px"}}>{isEditing?<div style={{display:"flex",alignItems:"center",gap:6}}><input type="number" min={0} value={editVal} onChange={e=>setEditVal(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")saveEdit(part,colorFilter);if(e.key==="Escape")setEditKey(null);}} autoFocus style={{width:64,padding:"4px 8px",borderRadius:6,border:"2px solid #0a3584",fontSize:13,fontWeight:700}}/><Btn small onClick={()=>saveEdit(part,colorFilter)}>✓</Btn><Btn small onClick={()=>setEditKey(null)} style={{background:"#dde3f0",color:"#6b7280"}}>✕</Btn></div>:<div style={{display:"flex",alignItems:"center",gap:8}}><span onClick={()=>editableKey?startEdit(part,colorFilter):null} title={editableKey?"Click to adjust":"Select a specific color to edit"} style={{fontWeight:700,fontSize:15,color:displayQty===0?"#ef4444":displayQty<=2?"#f59e0b":"#10b981",cursor:editableKey?"pointer":"default",borderBottom:editableKey?"1px dashed currentColor":"none"}}>{displayQty}</span>{colorFilter==="All"&&colorOpts&&<span style={{fontSize:11,color:"#6b7280",fontStyle:"italic"}}>total</span>}</div>}</td></tr>;
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ─── Finished Inventory ────────────────────────────────────────────────────────
function FinishedTab({finished,addFinishedCarts,updateFinishedCart,deleteFinishedCart,showToast,parts}) {
  const blankLine=()=>({_id:ulid(),vinNew:"",vinNewMode:"typed",vinLegacy:"",model:MODELS[0],body:BODY_COLORS[0],seat:SEAT_COLORS[0],notes:"",dateAdded:today()});
  const [lines,setLines]=useState([blankLine()]);
  const [adding,setAdding]=useState(false);
  const [editId,setEditId]=useState(null);
  const [editForm,setEditForm]=useState(null);
  const [filterModel,setFilterModel]=useState("All");
  const [searchQuery,setSearchQuery]=useState("");
  const [missingModal,setMissingModal]=useState(null);
  const [importing,setImporting]=useState(true);
  const [importLoading,setImportLoading]=useState(false);
  const [productionCarts,setProductionCarts]=useState([]);
  const [importError,setImportError]=useState(null);
  const [incompleteModal,setIncompleteModal]=useState(null);
  const available=finished.filter(c=>!c.status);
  const filtered=available.filter(c=>{
    if(!modelMatchesFilter(c.model,filterModel)) return false;
    if(searchQuery.trim()){
      const q=searchQuery.trim().toLowerCase();
      const haystack=[c.vinNew,c.vinLegacy,c.model,c.body,c.seat,c.notes,c.dateAdded].join(" ").toLowerCase();
      if(!haystack.includes(q)) return false;
    }
    return true;
  });
  const setLF=(lid,f,v)=>setLines(prev=>prev.map(l=>l._id===lid?{...l,[f]:v}:l));
  const getMissingParts=(line)=>{const bom=BOM[line.model];if(!bom) return [];const missing=[];for(const {p,q} of bom){const pt=PARTS.find(x=>x.id===p);const colorKey=partColorKey(pt,line.body,line.seat);const have=parts[psk(p,colorKey)]||0;if(have<q) missing.push({partName:pt?.name||p,colorKey,needed:q,have});}return missing;};
  const previewDeductions=(line)=>{const bom=BOM[line.model];if(!bom) return [];return bom.map(({p,q})=>{const pt=PARTS.find(x=>x.id===p);const colorKey=partColorKey(pt,line.body,line.seat);const currentQty=parts[psk(p,colorKey)]||0;return {part:pt,qty:q,colorKey,currentQty,afterQty:Math.max(0,currentQty-q)};});};
  const validateAndSubmit=async()=>{
    for(let i=0;i<lines.length;i++){const l=lines[i];if(l.vinNewMode==="typed"&&l.vinNew.trim().length===0){showToast(`Cart #${i+1}: New VIN (Last 4) is required`,"#ef4444");return;}if(!l.vinLegacy.trim()){showToast(`Cart #${i+1}: Legacy VIN (Last 4) is required`,"#ef4444");return;}const missing=getMissingParts(l);if(missing.length>0){setMissingModal({cartLabel:`Cart #${i+1} — ${l.model} · ${l.body} body · ${l.seat} seat`,missing});return;}}
    const cartsToAdd=lines.map(({_id,vinNewMode,...l})=>({...l,vinNew:vinNewMode==="na"?"N/A":l.vinNew}));
    await addFinishedCarts(cartsToAdd);setLines([blankLine()]);setAdding(false);};
  const loadProductionCarts=async()=>{setImportLoading(true);setImportError(null);try{const raw=await fetchReadyToShipCarts();const mapped=raw.map(c=>{const vin=c.vin||"";const body=mapShellColor(c.shellColor);const seat=mapSeatColor(c.seatColor);const mappedModel=mapModelName(c.model||"");return{_fbId:c.id,vin,legacyVin:vin.slice(-4),model:mappedModel,body,seat,shellColorRaw:c.shellColor,seatColorRaw:c.seatColor,modelRaw:c.model,bodyMapped:!!body,seatMapped:!!seat,modelValid:MODELS.includes(mappedModel)};});setProductionCarts(mapped);}catch(e){setImportError(`Failed: ${e?.message||"Unknown error"}`);}finally{setImportLoading(false);}};
  const handleImport=async()=>{
    if(!productionCarts.length) return;
    const dateStr=today();
    const toImport=productionCarts.filter(c=>c.bodyMapped&&c.seatMapped&&c.modelValid);
    const skipped=productionCarts.filter(c=>!c.bodyMapped||!c.seatMapped||!c.modelValid);
    // Prevent duplicates: check if cart with same Firebase ID (_fbId stored in notes or check by legacyVin+model) already exists
    const existingVinLegacyModels=new Set(finished.map(c=>`${c.vinLegacy}::${c.model}`));
    const existingFbIds=new Set(finished.map(c=>c.notes).filter(n=>n&&n.startsWith("fbid:")));
    const filtered=toImport.filter(c=>{
      const fbKey=`fbid:${c._fbId}`;
      const vinKey=`${c.legacyVin}::${c.model}`;
      return !existingFbIds.has(fbKey)&&!existingVinLegacyModels.has(vinKey);
    });
    const blocked=[];const cartsToAdd=[];
    for(const c of filtered){
      // Production carts are already built - no parts deduction needed
      // Store fbId in notes field for duplicate tracking (prefixed "fbid:")
      cartsToAdd.push({vinNew:"N/A",vinLegacy:c.legacyVin,model:c.model,body:c.body,seat:c.seat,notes:`fbid:${c._fbId}`,dateAdded:c.updatedAt||dateStr});
    }
    if(cartsToAdd.length>0) await addFinishedCarts(cartsToAdd,true);
    if(skipped.length>0){const allBlocked=skipped.map(c=>({vin:c.vin,model:c.modelValid?c.model:`${c.modelRaw||c.model} (unrecognized)`,body:c.body||c.shellColorRaw,seat:c.seat||c.seatColorRaw,missing:[...(!c.bodyMapped?[{partName:`Body color "${c.shellColorRaw}" not recognized`,colorKey:"any",needed:1,have:0}]:[]),...(!c.seatMapped?[{partName:`Seat color "${c.seatColorRaw}" not recognized`,colorKey:"any",needed:1,have:0}]:[]),...(!c.modelValid?[{partName:`Model "${c.model}" not recognized`,colorKey:"any",needed:1,have:0}]:[])]}));setIncompleteModal(allBlocked);}
    // productionCarts will be refreshed by the next auto-sync interval
  };
  const startEdit=c=>{setEditId(c.id);setEditForm({...c});};
  const saveEdit=async()=>{await updateFinishedCart(editId,editForm);setEditId(null);setEditForm(null);showToast("Cart updated ✓");};
  const byModel=useMemo(()=>{const m={};available.forEach(c=>{m[c.model]=(m[c.model]||0)+1;});return Object.entries(m).sort((a,b)=>b[1]-a[1]);},[finished]);
  // Track imported Firebase IDs to prevent duplicates
  const importedFbIdsRef = useRef(new Set(finished.map(c => c.notes).filter(Boolean)));
  
  // Auto-sync every 60 seconds and auto-import
  useEffect(()=>{
    loadProductionCarts();
    const interval = setInterval(loadProductionCarts, 60000);
    return () => clearInterval(interval);
  },[]);
  
  // Auto-import when productionCarts changes (once per refresh cycle)
  const [lastImportTime,setLastImportTime]=useState(0);
  useEffect(()=>{
    if(productionCarts.length>0&&!importLoading) {
      const now=Date.now();
      if(now-lastImportTime>30000) { // debounce: don't import more than once per 30s
        setLastImportTime(now);
        handleImport();
      }
    }
  },[productionCarts,lastImportTime]);

  return (
    <div>
      {missingModal&&<MissingPartsModal cartLabel={missingModal.cartLabel} missing={missingModal.missing} onClose={()=>setMissingModal(null)}/>}
      {incompleteModal&&<IncompleteImportModal blockedCarts={incompleteModal} onClose={()=>setIncompleteModal(null)}/>}
      <div style={{background:"#eff6ff",border:"1px solid #3b82f6",borderRadius:10,padding:"10px 14px",marginBottom:14,fontSize:13,color:"#1d4ed8"}}>ℹ️ <strong>Note:</strong> Adding a finished cart immediately deducts the full BOM from parts inventory.</div>
      {byModel.length>0&&<div style={{background:"#ffffff",borderRadius:14,padding:16,marginBottom:18,boxShadow:"0 1px 8px rgba(10,53,132,0.1)"}}><div style={{fontWeight:700,fontSize:13,color:"#0a3584",marginBottom:12}}>🏭 Finished Carts by Model</div><div style={{display:"flex",gap:10,flexWrap:"wrap"}}>{byModel.map(([model,count])=><div key={model} style={{background:"#f0fdf4",borderRadius:10,padding:"10px 16px",borderLeft:"4px solid #10b981",flex:"1 1 120px"}}><div style={{fontSize:22,fontWeight:800,color:"#10b981"}}>{count}</div><div style={{fontSize:12,color:"#6b7280",fontWeight:600,marginTop:1}}>{model}</div></div>)}<div style={{background:"#f8fafc",borderRadius:10,padding:"10px 16px",borderLeft:"4px solid #6366f1",flex:"1 1 120px"}}><div style={{fontSize:22,fontWeight:800,color:"#6366f1"}}>{available.length}</div><div style={{fontSize:12,color:"#6b7280",fontWeight:600,marginTop:1}}>Total Available</div></div></div></div>}
      <div style={{marginBottom:14}}>
        <input
          type="text"
          value={searchQuery}
          onChange={e=>setSearchQuery(e.target.value)}
          placeholder="🔍 Search by VIN, model, body, seat, notes…"
          style={{width:"100%",boxSizing:"border-box",padding:"9px 14px",borderRadius:10,border:"2px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#f8fafc",outline:"none"}}
        />
      </div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,flexWrap:"wrap",gap:10}}>
        <div style={{fontWeight:700,fontSize:15,color:"#0a3584"}}>Finished Inventory ({available.length})</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <Btn onClick={()=>{setAdding(a=>!a);setLines([blankLine()]);}}>{adding?"Cancel":"+ Add Finished Carts"}</Btn>
        </div>
      </div>
      {adding&&(
        <div style={{background:"#ffffff",borderRadius:12,padding:18,marginBottom:16,boxShadow:"0 2px 12px rgba(10,53,132,0.12)"}}>
          <div style={{fontWeight:700,marginBottom:4,color:"#0a3584"}}>Add Finished Carts</div>
          <div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>
            {lines.map((l,i)=>{const deductions=previewDeductions(l);const missingNow=getMissingParts(l);return(
              <div key={l._id} style={{background:i%2===0?"#f8fafc":"#fff",borderRadius:10,padding:"12px 14px",border:`1px solid ${missingNow.length>0?"#fca5a5":"#dde3f0"}`}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}><span style={{fontSize:12,fontWeight:700,color:"#6b7280"}}>Cart #{i+1}</span>{lines.length>1&&<Btn small danger onClick={()=>setLines(prev=>prev.filter(x=>x._id!==l._id))}>✕ Remove</Btn>}</div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(165px,1fr))",gap:10,marginBottom:10}}>
                  <VinNewInput value={l.vinNew} mode={l.vinNewMode} onValueChange={v=>setLF(l._id,"vinNew",v)} onModeChange={m=>setLF(l._id,"vinNewMode",m)}/>
                  <VinLegacyInput value={l.vinLegacy} onChange={v=>setLF(l._id,"vinLegacy",v)}/>
                  <Sel label="Model" val={l.model} opts={MODELS.map(m=>({v:m,l:m}))} onChange={v=>setLF(l._id,"model",v)}/>
                  <Sel label="Body Color" val={l.body} opts={BODY_COLORS.map(c=>({v:c,l:c}))} onChange={v=>setLF(l._id,"body",v)}/>
                  <Sel label="Seat Color" val={l.seat} opts={SEAT_COLORS.map(c=>({v:c,l:c}))} onChange={v=>setLF(l._id,"seat",v)}/>
                  <Field label="Date Added" type="date" val={l.dateAdded} onChange={v=>setLF(l._id,"dateAdded",v)}/>
                  <Field label="Notes" val={l.notes} onChange={v=>setLF(l._id,"notes",v)}/>
                </div>
                {missingNow.length>0&&<div style={{background:"#fef2f2",border:"1px solid #fca5a5",borderRadius:8,padding:"8px 12px",marginBottom:8}}><div style={{fontSize:12,fontWeight:700,color:"#991b1b",marginBottom:4}}>⚠️ Missing parts:</div><div style={{display:"flex",flexWrap:"wrap",gap:4}}>{missingNow.map((m,mi)=><span key={mi} style={{background:"#fee2e2",color:"#991b1b",borderRadius:5,padding:"2px 8px",fontSize:11,fontWeight:700}}>{m.partName}{m.colorKey!=="any"?` (${m.colorKey})`:""} — have {m.have}, need {m.needed}</span>)}</div></div>}
                <div style={{borderTop:"1px solid #e2e8f0",paddingTop:10}}><div style={{fontSize:11,fontWeight:700,color:"#6b7280",marginBottom:6,textTransform:"uppercase"}}>Parts deducted:</div><div style={{display:"flex",flexWrap:"wrap",gap:5}}>{deductions.map(({part,qty,colorKey,currentQty,afterQty},di)=><div key={di} style={{background:afterQty<0?"#fee2e2":"#f0fdf4",border:`1px solid ${afterQty<0?"#fca5a5":"#86efac"}`,borderRadius:6,padding:"3px 9px",fontSize:11,color:afterQty<0?"#991b1b":"#065f46"}}><strong>−{qty}</strong> {part?.name}{colorKey!=="any"?<span style={{marginLeft:3,opacity:0.7}}>{colorKey}</span>:null}<span style={{marginLeft:5,opacity:0.6}}>{currentQty}→{afterQty}</span>{afterQty<0&&<span style={{marginLeft:4,fontWeight:700}}>⚠️</span>}</div>)}</div></div>
              </div>
            );})}
          </div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
            <Btn onClick={()=>setLines(prev=>[...prev,blankLine()])} style={{background:"#dde3f0",color:"#6b7280"}}>+ Add Another</Btn>
            <Btn onClick={validateAndSubmit}>✓ Save All Carts &amp; Deduct Parts</Btn>
          </div>
        </div>
      )}
      <div style={{marginBottom:14}}><GroupedModelFilter value={filterModel} onChange={setFilterModel}/></div>
      <div style={{background:"#ffffff",borderRadius:12,overflow:"auto",boxShadow:"0 1px 6px rgba(10,53,132,0.08)"}}>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
          <thead><tr style={{background:"#f0f4fb"}}>{["New VIN (Last 4)","Legacy VIN (Last 4)","Model","Body","Seat","Date Added","Notes",""].map(h=><th key={h} style={{padding:"10px 14px",textAlign:"left",color:"#6b7280",fontWeight:700,borderBottom:"2px solid #dde3f0"}}>{h}</th>)}</tr></thead>
          <tbody>
            {filtered.map((c,i)=>(
              <>
                <tr key={c.id} style={{background:i%2===0?"#fff":"#f8fafc"}}>
                  <td style={{padding:"8px 14px",fontWeight:700,color:"#6366f1"}}>{c.vinNew||"N/A"}</td>
                  <td style={{padding:"8px 14px",color:"#6b7280",fontSize:12}}>{c.vinLegacy||"—"}</td>
                  <td style={{padding:"8px 14px",fontWeight:600}}>{c.model}</td>
                  <td style={{padding:"8px 14px"}}><ColorDot color={c.body}/>{c.body}</td>
                  <td style={{padding:"8px 14px"}}>{c.seat}</td>
                  <td style={{padding:"8px 14px",color:"#6b7280"}}>{c.dateAdded}</td>
                  <td style={{padding:"8px 14px",color:"#6b7280"}}>{c.notes&&!c.notes.startsWith("fbid:")?c.notes:"—"}</td>
                  <td style={{padding:"8px 14px"}}><div style={{display:"flex",gap:6}}><Btn small onClick={()=>{if(editId===c.id){setEditId(null);setEditForm(null);}else{startEdit(c);}}} style={{background:editId===c.id?"#e2e8f0":"#6366f1",color:editId===c.id?"#475569":"#fff"}}>{editId===c.id?"Cancel":"✏️ Edit"}</Btn><Btn small danger onClick={()=>deleteFinishedCart(c.id)}>✕</Btn></div></td>
                </tr>
                {editId===c.id&&editForm&&(
                  <tr key={`edit-${c.id}`}><td colSpan={9} style={{padding:"12px 14px",background:"#e8eef9",borderTop:"1px solid #1e4a6e",borderBottom:"2px solid #0ea5e9"}}>
                    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(150px,1fr))",gap:10,marginBottom:12}}>
                      <Field label="New VIN (Last 4)" val={editForm.vinNew||""} onChange={v=>setEditForm(f=>({...f,vinNew:v.replace(/\D/g,"").slice(0,4)}))}/>
                      <Field label="Legacy VIN (Last 4)" val={editForm.vinLegacy||""} onChange={v=>setEditForm(f=>({...f,vinLegacy:v.replace(/\D/g,"").slice(0,4)}))}/>
                      <Sel label="Model" val={editForm.model} opts={MODELS.map(m=>({v:m,l:m}))} onChange={v=>setEditForm(f=>({...f,model:v}))}/>
                      <Sel label="Body Color" val={editForm.body} opts={BODY_COLORS.map(c=>({v:c,l:c}))} onChange={v=>setEditForm(f=>({...f,body:v}))}/>
                      <Sel label="Seat Color" val={editForm.seat} opts={SEAT_COLORS.map(c=>({v:c,l:c}))} onChange={v=>setEditForm(f=>({...f,seat:v}))}/>
                      <Field label="Date Added" type="date" val={editForm.dateAdded||""} onChange={v=>setEditForm(f=>({...f,dateAdded:v}))}/>
                      <Field label="Notes" val={editForm.notes||""} onChange={v=>setEditForm(f=>({...f,notes:v}))}/>
                    </div>
                    <div style={{display:"flex",gap:10}}><Btn onClick={saveEdit}>💾 Save Changes</Btn><Btn onClick={()=>{setEditId(null);setEditForm(null);}} style={{background:"#dde3f0",color:"#6b7280"}}>Cancel</Btn></div>
                  </td></tr>
                )}
              </>
            ))}
            {filtered.length===0&&<tr><td colSpan={9} style={{textAlign:"center",padding:32,color:"#6b7280"}}>No finished carts.</td></tr>}
          </tbody>
        </table>
      </div>
      {importing&&(
        <div style={{background:"#ffffff",borderRadius:12,padding:18,marginBottom:16,boxShadow:"0 2px 12px rgba(124,58,237,0.12)",border:"1px solid #ddd6fe"}}>
          <div style={{fontWeight:700,fontSize:14,color:"#7c3aed",marginBottom:4}}>🔄 Live Ready-to-Ship Carts from Production</div>
          <div style={{fontSize:12,color:"#6b7280",marginBottom:14}}>Automatically fetches carts with status <strong>Ready to Ship</strong> from Production. New VIN → N/A, Legacy VIN → last 4 digits.</div>
          {importLoading&&<div style={{display:"flex",alignItems:"center",gap:10,color:"#7c3aed",fontSize:13,padding:"8px 0"}}>⏳ Connecting to Production Firebase…</div>}
          {importError&&<div style={{background:"#fef2f2",border:"1px solid #fca5a5",borderRadius:8,padding:"10px 14px",color:"#991b1b",fontSize:13,marginBottom:12}}>⚠️ {importError}<button onClick={loadProductionCarts} style={{marginLeft:12,background:"none",border:"none",color:"#7c3aed",fontWeight:700,cursor:"pointer",fontSize:12}}>Retry</button></div>}
          {productionCarts.length>0&&<>
            <div style={{fontSize:12,fontWeight:700,color:"#6b7280",marginBottom:10,textTransform:"uppercase"}}>{productionCarts.length} cart{productionCarts.length!==1?"s":""} found:</div>
            <div style={{display:"flex",flexDirection:"column",gap:6,marginBottom:14,maxHeight:340,overflowY:"auto"}}>
              {productionCarts.map((c,i)=>{const hasIssue=!c.bodyMapped||!c.seatMapped||!c.modelValid;const missingForCart=c.bodyMapped&&c.seatMapped&&c.modelValid?getMissingParts({model:c.model,body:c.body,seat:c.seat}):[];const hasMissingParts=missingForCart.length>0;return<div key={c._fbId} style={{borderRadius:9,padding:"10px 13px",border:`1px solid ${hasIssue||hasMissingParts?"#fca5a5":"#86efac"}`,background:hasIssue||hasMissingParts?"#fef2f2":"#f0fdf4",display:"flex",flexWrap:"wrap",gap:10,alignItems:"center"}}><div style={{flex:"1 1 220px"}}><div style={{fontWeight:700,fontSize:13,color:"#0a3584"}}>VIN: <span style={{color:"#6366f1"}}>{c.vin}</span></div><div style={{fontSize:12,color:"#6b7280",marginTop:3,display:"flex",gap:6,flexWrap:"wrap"}}><span style={{fontWeight:600,color:c.modelValid?"#0a3584":"#ef4444"}}>{c.model}{!c.modelValid?" ⚠️":""}</span><span>·</span><span style={{color:c.bodyMapped?"#6b7280":"#ef4444"}}><ColorDot color={c.body}/>{c.body||c.shellColorRaw}{!c.bodyMapped?" ⚠️":""}</span><span>·</span><span style={{color:c.seatMapped?"#6b7280":"#ef4444"}}>{c.seat||c.seatColorRaw}{!c.seatMapped?" ⚠️":""}</span></div></div><div>{hasIssue?<span style={{background:"#fee2e2",color:"#991b1b",borderRadius:6,padding:"3px 10px",fontSize:11,fontWeight:700}}>⛔ Skipped</span>:hasMissingParts?<span style={{background:"#fef3c7",color:"#92400e",borderRadius:6,padding:"3px 10px",fontSize:11,fontWeight:700}}>⚠️ Parts short</span>:<span style={{background:"#d1fae5",color:"#065f46",borderRadius:6,padding:"3px 10px",fontSize:11,fontWeight:700}}>✓ Ready</span>}</div></div>;})}
            </div>
          </>}
        </div>
      )}

    </div>
  );
}
async function exportOpenOrdersToExcel(orders: any[]) {
  const ExcelJS = (await import('exceljs')).default;
  // ── Pull VINs from all production Firebase statuses ──────────────────────
  const [readyToShip, active, inQueue, qcPassed] = await Promise.all([
    fetchReadyToShipCarts(),
    fetchActiveBuildsCarts(),
    fetchInQCQueueCarts(),
    fetchQCPassedCarts(),
  ]);
  const allProductionCarts = [...readyToShip, ...active, ...inQueue, ...qcPassed];

  // Build VIN lookup: dealer|model|color → vin
  const vinLookup = new Map();
  allProductionCarts.forEach((c) => {
    const key1 = `${c.dealerName||""}|${c.model||""}|${c.shellColor||""}`.toLowerCase();
    const key2 = `${c.dealerName||""}|${c.model||""}|${c.body||""}`.toLowerCase();
    if (c.vin) { vinLookup.set(key1, c.vin); vinLookup.set(key2, c.vin); }
  });

  // ── Group flat orders array by orderGroupId ───────────────────────────────
  const openOrders = orders.filter(o => o.status === "open");
  const groupMap: Record<string, {dealer: string; date: string; notes: string; carts: any[]}> = {};
  openOrders.forEach(o => {
    const gid = o.orderGroupId || o.id;
    if (!groupMap[gid]) groupMap[gid] = { dealer: o.customer || "", date: o.date || "", notes: o.notes || "", carts: [] };
    groupMap[gid].carts.push(o);
  });
  const groups = Object.values(groupMap).sort((a, b) => (a.date || "").localeCompare(b.date || ""));

  // ── Build workbook with ExcelJS (real style support) ──────────────────────
  const currentDate = new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });

  const wb = new ExcelJS.Workbook();
  const ws = wb.addWorksheet("Upcoming Orders");

  // Column widths
  ws.columns = [
    { width: 9  },   // A: Order #
    { width: 26 },   // B: Dealer
    { width: 15 },   // C: Cart Model
    { width: 24 },   // D: Color
    { width: 13 },   // E: VIN
    { width: 8  },   // F: Total
    { width: 22 },   // G: Est. Shipping Date
    { width: 32 },   // H: Notes
  ];

  // ── Shared fills ─────────────────────────────────────────────────────
  // Title row: navy
  const navyFill   = { type: "pattern", pattern: "solid", fgColor: { argb: "FF0A1F4E" } } as const;
  // Header row: black
  const blackFill  = { type: "pattern", pattern: "solid", fgColor: { argb: "FF000000" } } as const;
  // Even orders: white; odd orders: light blue tint
  const whiteFill  = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFFFFFF" } } as const;
  const tintFill   = { type: "pattern", pattern: "solid", fgColor: { argb: "FFD6E4F7" } } as const;

  const hairBorder = { style: "hair" as const, color: { argb: "FFCBD5E1" } };
  const thinBorder = { style: "thin" as const, color: { argb: "FF9CB3CC" } };
  const allHair = { top: hairBorder, bottom: hairBorder, left: hairBorder, right: hairBorder };
  const allThin = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };

  const applyStyle = (cell: ExcelJS.Cell, opts: {
    bold?: boolean; sz?: number; color?: string;
    fill?: any; hAlign?: string; vAlign?: string; border?: any;
  }) => {
    cell.font = { bold: opts.bold||false, size: opts.sz||10, color: { argb: opts.color||"FF1E293B" } };
    if (opts.fill) cell.fill = opts.fill;
    cell.alignment = {
      horizontal: (opts.hAlign||"left") as any,
      vertical:   (opts.vAlign||"middle") as any,
    };
    if (opts.border) cell.border = opts.border;
  };

  // ── Row 1: Title (navy, white bold, merged) ──────────────────────────
  ws.addRow([`Upcoming Orders — ${currentDate}`, "", "", "", "", "", "", ""]);
  ws.mergeCells("A1:H1");
  applyStyle(ws.getCell("A1"), { bold: true, sz: 13, color: "FFFFFFFF", fill: navyFill, hAlign: "center", vAlign: "middle" });
  ws.getRow(1).height = 26;

  // ── Row 2: Column headers (BLACK background, white bold) ─────────────
  const HEADERS = ["Order #", "Dealer", "Cart Model", "Color", "VIN", "Total", "Est. Shipping Date", "Notes"];
  ws.addRow(HEADERS);
  const headerRow = ws.getRow(2);
  headerRow.height = 20;
  headerRow.eachCell(cell => {
    applyStyle(cell, { bold: true, sz: 11, color: "FFFFFFFF", fill: blackFill, hAlign: "center", vAlign: "middle", border: allThin });
  });

  // ── Data rows ────────────────────────────────────────────────────────
  // Each order group alternates fill: even idx → white, odd idx → blue tint.
  // Cols A, B, F, G are merged vertically for the entire group.
  // Cols C, D, E, H get one row per cart with the same group fill.
  // VIN (E) and Total (F) get blue text.

  const blueFill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF1A56DB" } } as const;

  let dataRowNum = 3; // next Excel row index (1-based), starts after title + header

  groups.forEach((group, idx) => {
    const orderNum  = idx + 1;
    const cartCount = group.carts.length;
    const groupFill = idx % 2 === 0 ? whiteFill : tintFill;
    const startRow  = dataRowNum;
    const endRow    = dataRowNum + cartCount - 1;

    // Write one Excel row per cart; A, B, F, G, H will be merged after
    group.carts.forEach((cart, ci) => {
      const body  = cart.body  || "";
      const seat  = cart.seat  || "";
      const model = cart.model || "";
      const color = (body && seat) ? `${body} / ${seat}` : body || seat;
      const vinKey = `${group.dealer}|${model}|${body}`.toLowerCase();
      const vin   = cart.vinNew || cart.vin || vinLookup.get(vinKey) || "";

      ws.addRow([
        ci === 0 ? orderNum        : "",
        ci === 0 ? group.dealer    : "",
        model,
        color,
        vin,
        ci === 0 ? cartCount       : "",
        "",
        ci === 0 ? (group.notes||"") : "",
      ]);
      const row = ws.lastRow!;
      row.height = 18;

      // Col A: solid blue fill, white bold text, centered
      applyStyle(row.getCell(1), { bold: true, sz: 11, color: "FFFFFFFF", fill: blueFill, hAlign: "center", vAlign: "middle", border: allHair });

      // Cols B-H: group fill
      [2,3,4,5,6,7,8].forEach(c => {
        applyStyle(row.getCell(c), { fill: groupFill, border: allHair, vAlign: "middle" });
      });

      // Cart Model (C)
      applyStyle(row.getCell(3), { sz: 10, fill: groupFill, border: allHair, vAlign: "middle" });

      // Color (D)
      applyStyle(row.getCell(4), { sz: 10, fill: groupFill, border: allHair, vAlign: "middle" });

      // VIN (E) — blue text, centered
      applyStyle(row.getCell(5), { sz: 10, color: "FF1A56DB", fill: groupFill, hAlign: "center", vAlign: "middle", border: allHair });

      dataRowNum++;
    });

    // ── Merge A, B, F, G, H vertically across all cart rows in this group ──
    if (cartCount > 1) {
      ws.mergeCells(startRow, 1, endRow, 1); // col A
      ws.mergeCells(startRow, 2, endRow, 2); // col B
      ws.mergeCells(startRow, 6, endRow, 6); // col F
      ws.mergeCells(startRow, 7, endRow, 7); // col G
      ws.mergeCells(startRow, 8, endRow, 8); // col H
    }

    // Re-style merged top cells
    // Col A: blue fill, white bold, centered
    applyStyle(ws.getCell(startRow, 1), { bold: true, sz: 11, color: "FFFFFFFF", fill: blueFill, hAlign: "center", vAlign: "middle", border: allThin });
    ws.getCell(startRow, 1).value = orderNum;

    // Col B: Dealer name — bold, left-aligned
    applyStyle(ws.getCell(startRow, 2), { bold: true, sz: 11, fill: groupFill, vAlign: "middle", border: allThin });
    ws.getCell(startRow, 2).value = group.dealer;

    // Col F: Total — blue text, centered, bold
    applyStyle(ws.getCell(startRow, 6), { bold: true, sz: 11, color: "FF1A56DB", fill: groupFill, hAlign: "center", vAlign: "middle", border: allThin });
    ws.getCell(startRow, 6).value = cartCount;

    // Col G: Est. Shipping Date
    applyStyle(ws.getCell(startRow, 7), { fill: groupFill, border: allThin });
    ws.getCell(startRow, 7).value = "";

    // Col H: Notes
    applyStyle(ws.getCell(startRow, 8), { fill: groupFill, border: allThin });
    ws.getCell(startRow, 8).value = group.notes || "";

    // ── Spacer row between orders (skip after last group) ────────────────
    if (idx < groups.length - 1) {
      ws.addRow(["", "", "", "", "", "", "", ""]);
      const spacer = ws.lastRow!;
      spacer.height = 6;
      [1,2,3,4,5,6,7,8].forEach(c => {
        spacer.getCell(c).fill = { type: "pattern" as const, pattern: "solid" as const, fgColor: { argb: "FFF1F5F9" } };
        spacer.getCell(c).border = {};
      });
      dataRowNum++;
    }
  });

  // ── Write & download ─────────────────────────────────────────────────
  const buf = await wb.xlsx.writeBuffer();
  saveAs(
    new Blob([buf], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }),
    `upcoming-orders-${new Date().toISOString().slice(0, 10)}.xlsx`
  );
}
// ─── Orders Dashboard ─────────────────────────────────────────────────────────
function OrdersDashboard({orders,updateOrder}) {
  const [selectedDealer,setSelectedDealer]=useState("");

  // All active dealers from orders + shipped
  const open=orders.filter(o=>o.status==="open");
  const building=orders.filter(o=>o.status==="building");
  const shipped=orders.filter(o=>o.status==="shipped");
  const active=[...open,...building];

  // Build dealer data
  const dealerMap=useMemo(()=>{
    const m={};
    DEALERS.forEach(d=>{m[d]={openOrders:[],lastShipped:null,totalPurchasedYTD:0};});
    // Track any existing order dealer that is not in the approved dealer list without showing it in the dropdown
    orders.forEach(o=>{if(!m[o.customer]) m[o.customer]={openOrders:[],lastShipped:null,totalPurchasedYTD:0};});
    active.forEach(o=>{m[o.customer].openOrders.push(o);});
    const year=String(new Date().getFullYear());
    shipped.forEach(o=>{
      const d=o.shippedAt||o.shipDate||o.date||"";
      if(!m[o.customer]) m[o.customer]={openOrders:[],lastShipped:null,totalPurchasedYTD:0};
      if(!m[o.customer].lastShipped||d>m[o.customer].lastShipped) m[o.customer].lastShipped=d;
      if(String(d).slice(0,4)===year) m[o.customer].totalPurchasedYTD += moneyNumber(o.shippedAmount||o.orderAmount||0);
    });
    return m;
  },[orders]);

  const dealerOpenOrderCounts=useMemo(()=>{
    const m={};
    DEALERS.forEach(d=>{m[d]=new Set();});
    open.forEach(o=>{
      if(!m[o.customer]) m[o.customer]=new Set();
      m[o.customer].add(o.orderGroupId||o.id);
    });
    const out={};
    Object.entries(m).forEach(([dealer,set])=>{out[dealer]=set.size;});
    return out;
  },[open]);

  const dealerOptionLabel=d=>{
    const count=dealerOpenOrderCounts[d]||0;
    if(!count) return d;
    return `${d} - ${count} open ${count===1?"order":"orders"}`;
  };

  const allDealers=DEALERS;
  const displayDealers=selectedDealer===""?[]:selectedDealer==="All"?allDealers:[selectedDealer];

  return (
    <div style={{marginBottom:24}}>
      <div style={{fontWeight:800,fontSize:16,color:"#0a3584",marginBottom:4}}>📊 Orders Dashboard</div>
      <div style={{fontSize:13,color:"#6b7280",marginBottom:14}}>Current open &amp; ready-to-ship orders sorted by dealer.</div>

      {/* Dealer filter */}
      <div style={{display:"flex",gap:10,alignItems:"flex-end",marginBottom:16,flexWrap:"wrap"}}>
        <Sel label="Filter by Dealer" val={selectedDealer} opts={[{v:"",l:"Select Dealer"},{v:"All",l:"All Dealers"},...allDealers.map(d=>({v:d,l:dealerOptionLabel(d)}))]} onChange={setSelectedDealer} wide/>
      </div>

      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {displayDealers.map(dealer=>{
          const data=dealerMap[dealer];
          if(!data) return null;
          const dealerOrders=data.openOrders;
          const hasOpen=dealerOrders.length>0;

          return (
            <div key={dealer} style={{background:"#ffffff",borderRadius:10,boxShadow:"0 1px 6px rgba(10,53,132,0.08)",overflow:"hidden",border:"1px solid #dde3f0"}}>
              {/* Dealer header */}
              <div style={{background:"#0a3584",color:"#fff",padding:"8px 12px",display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:6}}>
                <div style={{fontWeight:800,fontSize:14}}>{dealer}</div>
                {!hasOpen&&<span style={{background:"rgba(255,255,255,0.15)",borderRadius:6,padding:"3px 12px",fontSize:12,fontWeight:600}}>No Open Orders</span>}
              </div>

              {/* Open orders for this dealer */}
              {hasOpen&&(
                <div style={{padding:"8px 12px",borderBottom:"1px solid #dde3f0"}}>
                  <div style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase",marginBottom:10}}>Open Orders</div>
                  <div style={{display:"flex",flexDirection:"column",gap:6}}>
                    {dealerOrders.map(o=>(
                      <div key={o.id} style={{background:"#f8fafc",borderRadius:8,padding:"7px 9px",border:"1px solid #dde3f0",display:"flex",flexWrap:"wrap",gap:8,alignItems:"center",fontSize:11}}>
                        <div style={{flex:"1 1 200px"}}>
                          <div style={{fontWeight:700,fontSize:12,color:"#0a3584"}}>{o.model} — <ColorDot color={o.body}/>{o.body} / {o.seat}</div>
                          <div style={{fontSize:11,color:"#6b7280",marginTop:1}}>{o.customization&&<span>{o.customization} · </span>}{o.notes&&<span style={{color:"#f59e0b"}}>{o.notes}</span>}</div>
                          {o.status==="building"&&<span style={{background:"#fef3c7",color:"#92400e",borderRadius:5,padding:"1px 8px",fontSize:11,fontWeight:700}}>Ready to Ship</span>}
                        </div>
                        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,fontSize:12,minWidth:220}}>
                          {/* Ship Date */}
                          <div>
                            <div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",marginBottom:3}}>Ship Date</div>
                            <input type="date" value={o.shipDate||""} onChange={e=>updateOrder(o.id,{shipDate:e.target.value})} style={{padding:"4px 8px",borderRadius:6,border:"1px solid #dde3f0",fontSize:12,color:"#0a3584",width:"100%"}}/>
                          </div>
                          {/* Paid status */}
                          <div>
                            <div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",marginBottom:3}}>Invoice Paid</div>
                            <span style={{background:o.paid?"#d1fae5":"#fee2e2",color:o.paid?"#065f46":"#991b1b",borderRadius:6,padding:"4px 10px",fontSize:12,fontWeight:700,display:"inline-block"}}>{o.paid?"Yes":"No"}</span>
                          </div>
                        </div>
                        {/* Truck Scheduled checkbox */}
                        <div>
                          <div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",marginBottom:3}}>Truck Scheduled</div>
                          <CheckField label="" checked={o.truckScheduled||false} onChange={v=>updateOrder(o.id,{truckScheduled:v})}/>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Footer stats */}
              <div style={{padding:"10px 18px",background:"#f8fafc",display:"flex",gap:20,flexWrap:"wrap",alignItems:"center"}}>
                <div>
                  <div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",marginBottom:2}}>Last Shipped</div>
                  <div style={{fontSize:13,fontWeight:700,color:data.lastShipped?"#0a3584":"#6b7280"}}>{data.lastShipped||"—"}</div>
                </div>
                <div>
                  <div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",marginBottom:2}}>Total $ Purchased YTD</div>
                  <div style={{fontSize:13,fontWeight:700,color:"#0a3584"}}>
                    <span>{formatMoney(data.totalPurchasedYTD||0)}</span>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
        {displayDealers.length===0&&<div style={{textAlign:"center",padding:24,color:"#6b7280",background:"#fff",borderRadius:12}}>Select a dealer to view orders.</div>}
      </div>
    </div>
  );
}

// ─── Create Orders (was Open Orders) ──────────────────────────────────────────
function OrdersTab({orders,finished,addOrders,updateOrder,deleteOrder,deleteOrders,calcTotalAvailable,showToast}) {
  const blankCart=()=>({_cid:ulid(),model:MODELS[0],body:BODY_COLORS[0],seat:SEAT_COLORS[0],customization:"",orderDate:today(),notes:""});
  const blankOrder=()=>({_id:ulid(),dealer:"",numCarts:1,carts:[blankCart()]});

  const [draftOrders,setDraftOrders]=useState([blankOrder()]);
  const [adding,setAdding]=useState(false);
  const [editId,setEditId]=useState(null);
  const [page,setPage]=useState(0);
  const [drillOrders,setDrillOrders]=useState(null);
  const [drillTitle,setDrillTitle]=useState("");
  const [selected,setSelected]=useState(new Set());
  const [confirmDelete,setConfirmDelete]=useState(null);

  const setOrderField = (oid,field,val) => {
    setDraftOrders(prev=>prev.map(o=>{
      if(o._id!==oid) return o;
      if(field==="numCarts"){
        const n=Math.max(1,val);
        const carts=Array.from({length:n},(_,i)=>o.carts[i]||blankCart());
        return {...o,numCarts:n,carts};
      }
      return {...o,[field]:val};
    }));
  };

  const setCartField = (oid,cid,field,val) => {
    setDraftOrders(prev=>prev.map(o=>{
      if(o._id!==oid) return o;
      return {...o,carts:o.carts.map(c=>c._cid!==cid?c:{...c,[field]:val})};
    }));
  };

  const submitOrders = async () => {
    for(const o of draftOrders){
      if(!o.dealer){showToast("Please select a dealer for all orders","#ef4444");return;}
    }
    const allCarts=[];
    for(const o of draftOrders){
      const groupId=makeOrderGroupId();
      for(const c of o.carts){
        allCarts.push({
          orderGroupId:groupId,model:c.model,body:c.body,seat:c.seat,customer:o.dealer,
          customization:c.customization||"",date:c.orderDate||today(),notes:c.notes||"",status:"open",
          vinNew:"",vinLegacy:"",vehicleType:"LSV",serialNumber:"",shipQuote:false,paid:false,
          estimateCreated:false,dealerDirectFinance:false,truckScheduled:false,shipDate:"",orderAmount:"",
          shippedAmount:"",shippedAt:"",orderQueuePosition:0,
        });
      }
    }
    const ok=await addOrders(allCarts);
    if(ok){setAdding(false);setDraftOrders([blankOrder()]);}
  };

  const open=orders.filter(o=>o.status==="open");
  const filteredOpen=[...open].sort((a,b)=>(a.date||"").localeCompare(b.date||""));

  const filteredOpenGroups=useMemo(()=>{
    const m={};
    filteredOpen.forEach(o=>{
      const gid=o.orderGroupId||o.id;
      if(!m[gid]) m[gid]={id:gid,dealer:o.customer,date:o.date,orders:[]};
      m[gid].orders.push(o);
      if((o.date||"") < (m[gid].date||"")) m[gid].date=o.date;
    });
    return Object.values(m);
  },[filteredOpen]);
  const totalPages=Math.max(1,Math.ceil(filteredOpenGroups.length/PAGE_SIZE));
  const safePage=Math.min(page,totalPages-1);
  const groupedPageOrders=filteredOpenGroups.slice(safePage*PAGE_SIZE,(safePage+1)*PAGE_SIZE);

  const BODY_OPTS=["TBD",...BODY_COLORS];
  const SEAT_OPTS=["TBD",...SEAT_COLORS];

  const toggleSelectGroup=group=>setSelected(prev=>{
    const n=new Set(prev);
    const all=group.orders.every(o=>n.has(o.id));
    group.orders.forEach(o=>{if(all) n.delete(o.id); else n.add(o.id);});
    return n;
  });
  const toggleAll=()=>{
    const ids=groupedPageOrders.flatMap(g=>g.orders.map(o=>o.id));
    const all=ids.length>0&&ids.every(id=>selected.has(id));
    setSelected(all?new Set():new Set(ids));
  };
  const clearSelection=()=>setSelected(new Set());
  const exportSelected=()=>{
    const sel=filteredOpen.filter(o=>selected.has(o.id));
    const yesNo=v=>v?"Yes":"No";
    exportCSV([
      ["Model","Body Color","Seat Color","Dealer","Vehicle Type","New VIN","Legacy VIN","Serial Number","Order Date","Ship Date","Ship Quote","Paid","Estimate / Invoice Created","Dealer Direct Finance","Truck Scheduled","Certificate Sent","Certificate Sent Date","Customization","Notes"],
      ...sel.map(o=>[o.model,o.body,o.seat,o.customer,o.vehicleType||"LSV",o.vinNew||"",o.vinLegacy||"",o.serialNumber||"",o.date||"",o.shipDate||"",yesNo(o.shipQuote),yesNo(o.paid),yesNo(o.estimateCreated),yesNo(o.dealerDirectFinance),yesNo(o.truckScheduled),yesNo(o.certSent),o.certSentDate||"",o.customization||"",o.notes||""])
    ],"selected-orders-"+today()+".csv");
  };
  const openDrill=(title,ords)=>{setDrillTitle(title);setDrillOrders(ords);};

  return (
    <div>
      {drillOrders&&<DrillModal title={drillTitle} orders={drillOrders} onClose={()=>setDrillOrders(null)}/>}
      {confirmDelete&&<ConfirmDialog msg={confirmDelete.ids?`Remove ${confirmDelete.ids.length} selected order(s)?`:"Remove this order?"} onYes={async()=>{if(confirmDelete.ids){await deleteOrders(confirmDelete.ids);clearSelection();}else await deleteOrder(confirmDelete.id);setConfirmDelete(null);}} onNo={()=>setConfirmDelete(null)}/>}

      {/* Orders Dashboard */}
      <OrdersDashboard orders={orders} updateOrder={updateOrder}/>


      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10,flexWrap:"wrap",gap:8}}>
        <div style={{fontWeight:700,fontSize:15,color:"#0a3584"}}>Open Orders ({filteredOpenGroups.length})</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <Btn small onClick={()=>exportOpenOrdersToExcel(orders)} style={{background:"#10b981",color:"#fff"}}>📥 Export Orders</Btn>
          <Btn onClick={()=>{setAdding(a=>!a);setEditId(null);setDraftOrders([blankOrder()]);}}>{adding?"Cancel":"+ Create Order"}</Btn>
        </div>
      </div>

      {adding&&(
        <div style={{background:"#ffffff",borderRadius:12,padding:18,marginBottom:16,boxShadow:"0 2px 12px rgba(10,53,132,0.12)"}}>
          <div style={{fontWeight:700,marginBottom:12,color:"#0a3584",fontSize:15}}>New Order</div>
          <div style={{display:"flex",flexDirection:"column",gap:16}}>
            {draftOrders.map((o,oi)=>(
              <div key={o._id} style={{background:"#f8fafc",borderRadius:12,padding:"16px",border:"1px solid #dde3f0"}}>
                {/* Order header — dealer + cart count (shown once) */}
                <div style={{display:"flex",gap:12,flexWrap:"wrap",alignItems:"flex-end",marginBottom:14,paddingBottom:14,borderBottom:"2px solid #dde3f0"}}>
                  <div style={{flex:"1 1 200px"}}>
                    <label style={{display:"flex",flexDirection:"column",gap:3}}>
                      <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Dealer *</span>
                      <select value={o.dealer} onChange={e=>setOrderField(o._id,"dealer",e.target.value)} style={{padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#f0f4f8"}}>
                        <option value="">— Select Dealer —</option>
                        {DEALERS.map(d=><option key={d} value={d}>{d}</option>)}
                      </select>
                    </label>
                  </div>
                  <div style={{minWidth:120}}>
                    <label style={{display:"flex",flexDirection:"column",gap:3}}>
                      <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Carts in Order</span>
                      <select value={o.numCarts} onChange={e=>setOrderField(o._id,"numCarts",parseInt(e.target.value))} style={{padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#f0f4f8"}}>
                        {Array.from({length:10},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}
                      </select>
                    </label>
                  </div>
                  {o.dealer&&<div style={{fontSize:13,fontWeight:700,color:"#0a3584",alignSelf:"center",background:"#eff6ff",borderRadius:8,padding:"6px 14px",border:"1px solid #bae6fd"}}>📋 Order for: <strong>{o.dealer}</strong> ({o.numCarts} cart{o.numCarts!==1?"s":""})</div>}
                  {draftOrders.length>1&&<Btn small danger onClick={()=>setDraftOrders(prev=>prev.filter(x=>x._id!==o._id))}>✕ Remove Order</Btn>}
                </div>

                {/* Individual cart details */}
                <div style={{display:"flex",flexDirection:"column",gap:10}}>
                  {(o.carts||[]).map((c,ci)=>(
                    <div key={c._cid} style={{background:"#ffffff",borderRadius:10,padding:"12px 14px",border:"1px solid #e2e8f0"}}>
                      <div style={{fontSize:12,fontWeight:800,color:"#6366f1",marginBottom:10}}>Cart #{ci+1}</div>
                      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(155px,1fr))",gap:10}}>
                        <Sel label="Model" val={c.model} opts={MODELS.map(m=>({v:m,l:m}))} onChange={v=>setCartField(o._id,c._cid,"model",v)}/>
                        <Sel label="Body Color" val={c.body} opts={BODY_OPTS.map(v=>({v,l:v}))} onChange={v=>setCartField(o._id,c._cid,"body",v)}/>
                        <Sel label="Seat Color" val={c.seat} opts={SEAT_OPTS.map(v=>({v,l:v}))} onChange={v=>setCartField(o._id,c._cid,"seat",v)}/>
                        <Field label="Customization" val={c.customization} onChange={v=>setCartField(o._id,c._cid,"customization",v)}/>
                        <Field label="Order Date" type="date" val={c.orderDate} onChange={v=>setCartField(o._id,c._cid,"orderDate",v)}/>
                        <Field label="Notes" val={c.notes} onChange={v=>setCartField(o._id,c._cid,"notes",v)}/>
                      </div>
                      <div style={{marginTop:10}}>
                        <FinishedBodyColorWheel finished={finished} model={c.model}/>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap",marginTop:12}}>
            <Btn onClick={()=>setDraftOrders(prev=>[...prev,blankOrder()])} style={{background:"#dde3f0",color:"#6b7280"}}>+ Add Another Order</Btn>
            <Btn onClick={submitOrders}>✓ Save All Orders</Btn>
          </div>
        </div>
      )}

      {selected.size>0&&(
        <div style={{background:"#0a3584",borderRadius:10,padding:"10px 14px",marginBottom:10,display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}>
          <span style={{color:"#fff",fontWeight:700,fontSize:13}}>{new Set(filteredOpen.filter(o=>selected.has(o.id)).map(o=>o.orderGroupId||o.id)).size} selected order(s)</span>
          <Btn small onClick={exportSelected} style={{background:"#10b981",color:"#fff"}}>📥 Export</Btn>
          <Btn small danger onClick={()=>setConfirmDelete({ids:[...selected]})}>🗑 Delete</Btn>
          <Btn small onClick={clearSelection} style={{background:"#334155",color:"#6b7280"}}>✕ Clear</Btn>
        </div>
      )}

      <Pager page={safePage} total={totalPages} count={filteredOpenGroups.length} onPage={setPage}/>
      <div style={{display:"flex",flexDirection:"column",gap:8,marginTop:8}}>
        {groupedPageOrders.length>0&&(
          <div style={{display:"flex",alignItems:"center",gap:8,padding:"4px 2px"}}>
            <input type="checkbox" checked={groupedPageOrders.length>0&&groupedPageOrders.every(g=>g.orders.every(o=>selected.has(o.id)))} onChange={toggleAll} style={{width:15,height:15,cursor:"pointer"}}/>
            <span style={{fontSize:12,color:"#6b7280",fontWeight:600}}>Select all on this page</span>
          </div>
        )}
        {groupedPageOrders.map(group=>{
          const isGroup=group.orders.length>1;
          return (
            <div key={group.id} style={{background:"#ffffff",borderRadius:12,boxShadow:"0 1px 6px rgba(10,53,132,0.08)",overflow:"hidden",outline:group.orders.every(o=>selected.has(o.id))?"2px solid #6366f1":"none"}}>
              <div style={{background:isGroup?"#eff6ff":"#fff",padding:"10px 14px",borderBottom:isGroup?"1px solid #bae6fd":"none",display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
                <input type="checkbox" checked={group.orders.every(o=>selected.has(o.id))} onChange={()=>toggleSelectGroup(group)} style={{width:15,height:15,cursor:"pointer",flexShrink:0}}/>
                <div style={{flex:"1 1 260px"}}>
                  <div style={{fontWeight:800,color:"#0a3584",fontSize:13}}>{isGroup?`Order — ${group.orders.length} carts`:"Order — 1 cart"} · <strong>{group.dealer}</strong></div>
                  <div style={{fontSize:12,color:"#6b7280",marginTop:2}}>Order date: {group.date}</div>
                </div>
                <Btn small danger onClick={()=>setConfirmDelete({ids:group.orders.map(o=>o.id)})}>Delete Order</Btn>
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:6,padding:"8px 14px"}}>
                {group.orders.map(o=>{
                  const avail=(o.seat!=="TBD"&&o.body!=="TBD")?calcTotalAvailable(o.model,o.body,o.seat):null;
                  const isEditing=editId===o.id;
                  return (
                    <div key={o.id} style={{border:"1px solid #dde3f0",borderRadius:10,background:"#f8fafc",outline:selected.has(o.id)?"2px solid #6366f1":"none"}}>
                      <div style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",flexWrap:"wrap"}}>
                        <div style={{flex:"1 1 280px"}}>
                          <div style={{fontWeight:700,color:"#0a3584",fontSize:13}}>{o.model}</div>
                          <div style={{marginTop:4,display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
                            <span style={{fontSize:14,fontWeight:700,color:o.body==="TBD"?"#f59e0b":"#334155"}}><ColorDot color={o.body}/>{o.body}</span>
                            <span style={{color:"#6b7280"}}>·</span>
                            <span style={{fontSize:14,fontWeight:700,color:o.seat==="TBD"?"#f59e0b":"#334155"}}>{o.seat}</span>
                            <span style={{color:"#6b7280"}}>·</span>
                            <span style={{fontSize:12,color:"#6b7280"}}>{o.date}</span>
                            {o.customization&&<><span style={{color:"#6b7280"}}>·</span><span style={{fontSize:12,color:"#6b7280"}}>{o.customization}</span></>}
                            {o.notes&&<><span style={{color:"#6b7280"}}>·</span><span style={{fontSize:12,color:"#f59e0b"}}>{o.notes}</span></>}
                          </div>
                        </div>
                        <div style={{display:"flex",alignItems:"center",gap:8}}>
                          <span style={{fontSize:12,fontWeight:700,color:avail===null?"#f59e0b":avail>0?"#10b981":"#ef4444"}}>{avail===null?"TBD":avail>0?`✓ ${avail} avail`:"✗ Parts short"}</span>
                          <Btn small onClick={()=>setEditId(isEditing?null:o.id)} style={{background:isEditing?"#e2e8f0":"#6366f1",color:isEditing?"#475569":"#fff"}}>{isEditing?"Cancel":"✏️ Edit"}</Btn>
                        </div>
                      </div>
                      {isEditing&&<EditOrderForm order={o} finished={finished} onSave={u=>saveEdit(o.id,u)} onCancel={()=>setEditId(null)}/>}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
        {filteredOpenGroups.length===0&&<div style={{textAlign:"center",padding:40,color:"#6b7280"}}>No open orders.</div>}
      </div>
      {totalPages>1&&<Pager page={safePage} total={totalPages} count={filteredOpenGroups.length} onPage={setPage} style={{marginTop:12}}/>}
    </div>
  );
}

// ─── Pager ────────────────────────────────────────────────────────────────────
function Pager({page,total,count,onPage,style={}}) {
  if(total<=1) return null;
  const btnStyle=(disabled)=>({padding:"5px 10px",borderRadius:7,border:"1px solid #dde3f0",background:disabled?"#f8fafc":"#fff",cursor:disabled?"default":"pointer",color:disabled?"#cbd5e1":"#475569",fontWeight:700,fontSize:12});
  return (
    <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap",...style}}>
      <button onClick={()=>onPage(0)} disabled={page===0} style={btnStyle(page===0)}>«</button>
      <button onClick={()=>onPage(page-1)} disabled={page===0} style={btnStyle(page===0)}>‹ Prev</button>
      <span style={{fontSize:13,color:"#6b7280",fontWeight:600}}>Page {page+1} of {total} <span style={{fontWeight:400,color:"#6b7280"}}>({count} total)</span></span>
      <button onClick={()=>onPage(page+1)} disabled={page===total-1} style={btnStyle(page===total-1)}>Next ›</button>
      <button onClick={()=>onPage(total-1)} disabled={page===total-1} style={btnStyle(page===total-1)}>»</button>
    </div>
  );
}

// ─── Edit Order Form ──────────────────────────────────────────────────────────
function EditOrderForm({order,finished=[],onSave,onCancel,showCert}) {
  const [form,setForm]=useState({...order});
  const BODY_OPTS=["TBD",...BODY_COLORS];const SEAT_OPTS=["TBD",...SEAT_COLORS];
  return (
    <div style={{borderTop:"2px solid #dde3f0",padding:"14px 16px",background:"#f8fafc"}}>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(155px,1fr))",gap:10,marginBottom:12}}>
        <VinNewInput label="New VIN (Last 4)" value={form.vinNew||""} mode={form.vinNewMode||"typed"} onValueChange={v=>setForm(f=>({...f,vinNew:v}))} onModeChange={m=>setForm(f=>({...f,vinNewMode:m}))}/>
        <VinLegacyInput label="Legacy VIN (Last 4)" value={form.vinLegacy||""} onChange={v=>setForm(f=>({...f,vinLegacy:v}))}/>
        <Sel label="Model" val={form.model} opts={MODELS.map(m=>({v:m,l:m}))} onChange={v=>setForm(f=>({...f,model:v}))}/>
        <Sel label="Body Color" val={form.body} opts={BODY_OPTS.map(c=>({v:c,l:c}))} onChange={v=>setForm(f=>({...f,body:v}))}/>
        <Sel label="Seat Color" val={form.seat} opts={SEAT_OPTS.map(c=>({v:c,l:c}))} onChange={v=>setForm(f=>({...f,seat:v}))}/>
        <label style={{display:"flex",flexDirection:"column",gap:3}}>
          <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Dealer</span>
          <select value={form.customer||""} onChange={e=>setForm(f=>({...f,customer:e.target.value}))} style={{padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#f0f4f8"}}>
            <option value="">— Select Dealer —</option>
            {DEALERS.map(d=><option key={d} value={d}>{d}</option>)}
          </select>
        </label>
        <Field label="Customization" val={form.customization||""} onChange={v=>setForm(f=>({...f,customization:v}))}/>
        <Field label="Order Date" type="date" val={form.date||""} onChange={v=>setForm(f=>({...f,date:v}))}/>
        <Field label="Notes" val={form.notes||""} onChange={v=>setForm(f=>({...f,notes:v}))}/>
      </div>
      <div style={{marginBottom:12}}>
        <FinishedBodyColorWheel finished={finished} model={form.model}/>
      </div>
      {showCert&&(
        <div style={{borderTop:"1px solid #dde3f0",paddingTop:12,marginBottom:12}}>
          <div style={{fontWeight:700,fontSize:13,color:"#0a3584",marginBottom:10}}>📄 Certificate</div>
          <div style={{display:"flex",gap:12,alignItems:"flex-end",flexWrap:"wrap"}}>
            <label style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer",fontSize:13,fontWeight:600,color:form.certSent?"#10b981":"#475569"}}>
              <input type="checkbox" checked={!!form.certSent} onChange={e=>{const checked=e.target.checked;const nd=checked?(form.certSentDate||today()):"";setForm(f=>({...f,certSent:checked,certSentDate:nd}));}} style={{width:16,height:16,cursor:"pointer"}}/>
              Certificate Sent
            </label>
            <Field label="Date Sent" type="date" val={form.certSentDate||""} onChange={v=>setForm(f=>({...f,certSentDate:v}))}/>
          </div>
        </div>
      )}
      <div style={{display:"flex",gap:10}}>
        <Btn onClick={()=>onSave(form)}>💾 Save Changes</Btn>
        <Btn onClick={onCancel} style={{background:"#dde3f0",color:"#6b7280"}}>Cancel</Btn>
      </div>
    </div>
  );
}

// ─── Build & Ship ─────────────────────────────────────────────────────────────
function BuildShipTab({orders,updateOrder,finished,updateFinishedCart,deleteFinishedCart,applyPartsChange,moveTo,reorderOrders,countFinished,calcTotalAvailable,calcPartsBuildable,parts,showToast}) {
  const [groupPickModal,setGroupPickModal]=useState(null);
  const [groupBuildSelections,setGroupBuildSelections]=useState({});
  const [detailOrder,setDetailOrder]=useState(null);
  const [openPage,setOpenPage]=useState(0);
  const [dragOrderId,setDragOrderId]=useState(null);

  const open=orders.filter(o=>o.status==="open");
  const building=orders.filter(o=>o.status==="building");
  const shipped=orders.filter(o=>o.status==="shipped");

  // Helper: check if all required checkboxes are checked for an order
  const allChecked=(o)=>{
    if(o.vehicleType==="LSV"){
      return o.shipQuote&&o.paid&&o.estimateCreated&&o.dealerDirectFinance&&o.certSent;
    }
    return o.shipQuote&&o.paid&&o.estimateCreated&&o.dealerDirectFinance;
  };


  const orderGroups=useMemo(()=>{
    const m={};
    open.forEach(o=>{
      const gid=o.orderGroupId||o.id;
      if(!m[gid]) m[gid]={id:gid,dealer:o.customer,date:o.date,orders:[]};
      m[gid].orders.push(o);
      if((o.date||"") < (m[gid].date||"")) m[gid].date=o.date;
    });
    return Object.values(m).sort((a,b)=>(a.date||"").localeCompare(b.date||""));
  },[open]);

  const canUsePartsFromMap=(partsMap,o)=>{
    if(o.seat==="TBD"||o.body==="TBD") return false;
    const bom=BOM[o.model];
    if(!bom) return false;
    for(const {p,q} of bom){
      const pt=PARTS.find(x=>x.id===p);
      const k=psk(p,partColorKey(pt,o.body,o.seat));
      if((partsMap[k]||0)<q) return false;
    }
    return true;
  };

  const deductPartsFromMap=(partsMap,o)=>{
    const next={...partsMap};
    for(const {p,q} of BOM[o.model]){
      const pt=PARTS.find(x=>x.id===p);
      const k=psk(p,partColorKey(pt,o.body,o.seat));
      next[k]=(next[k]||0)-q;
    }
    return next;
  };

  const canFillGroup=useCallback((group)=>{
    const usedFinished=new Set();
    let virtualParts={...parts};
    for(const o of group.orders){
      if(o.seat==="TBD"||o.body==="TBD") return false;
      const fc=getAvailableFinishedCarts(finished,o.model,o.body,o.seat).find(c=>!usedFinished.has(c.id));
      if(fc){
        usedFinished.add(fc.id);
        continue;
      }
      if(!canUsePartsFromMap(virtualParts,o)) return false;
      virtualParts=deductPartsFromMap(virtualParts,o);
    }
    return true;
  },[finished,parts]);

  const openGroupBuildPicker=(group)=>{
    if(!canFillGroup(group)){
      showToast("Cannot build this order until every cart in the order is fillable","#ef4444");
      return;
    }
    setGroupBuildSelections({});
    setGroupPickModal(group);
  };

  const confirmGroupBuild=async()=>{
    const group=groupPickModal;
    if(!group) return;
    const usedFinished=new Set();
    let virtualParts={...parts};
    const plan=[];

    for(const o of group.orders){
      if(o.seat==="TBD"||o.body==="TBD"){showToast("Cannot build: one or more carts still has TBD color","#ef4444");return;}
      const matches=getAvailableFinishedCarts(finished,o.model,o.body,o.seat).filter(c=>!usedFinished.has(c.id));
      const selected=groupBuildSelections[o.id] || (matches.length===0 ? "__parts" : "");
      if(!selected){
        showToast("Select an inventory cart or choose Build from Parts for every cart in the order","#ef4444");
        return;
      }
      if(selected!=="__parts"){
        const fc=matches.find(c=>c.id===selected);
        if(!fc){showToast("Selected inventory cart is no longer available. Reopen the picker and try again.","#ef4444");return;}
        usedFinished.add(fc.id);
        plan.push({order:o,source:"finished",finishedCart:fc});
      } else {
        if(!canUsePartsFromMap(virtualParts,o)){
          showToast(`Not enough parts to build ${o.model} ${o.body}/${o.seat} from parts`,"#ef4444");
          return;
        }
        virtualParts=deductPartsFromMap(virtualParts,o);
        plan.push({order:o,source:"parts"});
      }
    }

    for(const item of plan){
      const o=item.order;
      if(item.source==="finished"){
        const fc=item.finishedCart;
        await updateFinishedCart(fc.id,{status:"reserved",reservedFor:o.id});
        await updateOrder(o.id,{status:"building",buildSource:"finished",finishedCartId:fc.id,partsRestored:false,vinNew:o.vinNew||fc.vinNew,vinLegacy:o.vinLegacy||fc.vinLegacy});
      } else {
        await applyPartsChange(o.model,o.body,o.seat,-1);
        await updateOrder(o.id,{status:"building",buildSource:"parts",partsRestored:false});
      }
    }
    setGroupPickModal(null);
    setGroupBuildSelections({});
    showToast(`🔧 Started full order build: ${group.orders.length} cart(s) → ${group.dealer}`,"#f59e0b");
  };

  const sortOpenQueue=(a,b)=>{
    const ap=a.orderQueuePosition||999999;
    const bp=b.orderQueuePosition||999999;
    if(ap!==bp) return ap-bp;
    const dateSort=(a.date||"").localeCompare(b.date||"");
    return dateSort;
  };
  const filteredOpen=[...open].sort(sortOpenQueue);
  const filteredOpenGroups=useMemo(()=>{
    const m={};
    filteredOpen.forEach(o=>{
      const gid=o.orderGroupId||o.id;
      if(!m[gid]) m[gid]={id:gid,dealer:o.customer,date:o.date,position:o.orderQueuePosition||999999,orders:[]};
      m[gid].orders.push(o);
      m[gid].position=Math.min(m[gid].position,o.orderQueuePosition||999999);
      if((o.date||"")<(m[gid].date||"")) m[gid].date=o.date;
    });
    return Object.values(m).sort((a,b)=>a.position!==b.position?a.position-b.position:(a.date||"").localeCompare(b.date||""));
  },[filteredOpen]);
  const moveOpenOrderInQueue=async(dragGroupId,targetGroupId)=>{
    if(!dragGroupId||!targetGroupId||dragGroupId===targetGroupId) return;
    const ids=filteredOpenGroups.map(g=>g.id);
    const from=ids.indexOf(dragGroupId);
    const to=ids.indexOf(targetGroupId);
    if(from<0||to<0) return;
    const [moved]=ids.splice(from,1);
    ids.splice(to,0,moved);
    await reorderOrders(ids);
    setDragOrderId(null);
  };
  const filteredBuilding=building;
  const filteredShipped=[...shipped].sort((a,b)=>(b.date||"").localeCompare(a.date||""));

  const openTotalPages=Math.max(1,Math.ceil(filteredOpenGroups.length/PAGE_SIZE));
  const safeOpenPage=Math.min(openPage,openTotalPages-1);
  const openPageGroups=filteredOpenGroups.slice(safeOpenPage*PAGE_SIZE,(safeOpenPage+1)*PAGE_SIZE);

  const openDetail=o=>setDetailOrder({...orders.find(x=>x.id===o.id)||o});

  // Weekly shipped grouping
  const weekMapShipped=useMemo(()=>{
    const m={};
    filteredShipped.forEach(o=>{const dateStr=o.date||today();const {key,sun,sat}=getWeekKey(dateStr);if(!m[key]) m[key]={sun,sat,key,orders:[]};m[key].orders.push(o);});
    return Object.values(m).sort((a,b)=>b.key.localeCompare(a.key));
  },[filteredShipped]);
  const [expandedShipWeeks,setExpandedShipWeeks]=useState(new Set());
  const toggleShipWeek=k=>setExpandedShipWeeks(prev=>{const n=new Set(prev);n.has(k)?n.delete(k):n.add(k);return n;});

  const buildVehicleExportRows=(list,dateLabel)=>{
    const yesNo=v=>v?"Yes":"No";
    const lsv=list.filter(o=>(o.vehicleType||"LSV")!=="Golf Cart");
    const golf=list.filter(o=>(o.vehicleType||"LSV")==="Golf Cart");
    return [
      ["LSV Orders"],
      ["New VIN","Legacy VIN","Model","Body Color","Seat Color","Dealer",dateLabel,"Customization","Build Source","Ship Quote","Paid","Estimate / Invoice Created","Dealer Direct Finance","Truck Scheduled","Certificate Sent","Notes"],
      ...lsv.map(o=>[o.vinNew||"",o.vinLegacy||"",o.model,o.body,o.seat,o.customer,dateLabel==="Ship Date"?(o.shipDate||o.date||""):(o.date||""),o.customization||"",o.buildSource==="finished"?"Finished Cart":"Parts Build",yesNo(o.shipQuote),yesNo(o.paid),yesNo(o.estimateCreated),yesNo(o.dealerDirectFinance),yesNo(o.truckScheduled),yesNo(o.certSent),o.notes||""]),
      [],
      ["Golf Cart Orders"],
      ["Serial #","Model","Body Color","Seat Color","Dealer",dateLabel,"Customization","Build Source","Ship Quote","Paid","Estimate / Invoice Created","Dealer Direct Finance","Truck Scheduled","Notes"],
      ...golf.map(o=>[o.serialNumber||"",o.model,o.body,o.seat,o.customer,dateLabel==="Ship Date"?(o.shipDate||o.date||""):(o.date||""),o.customization||"",o.buildSource==="finished"?"Finished Cart":"Parts Build",yesNo(o.shipQuote),yesNo(o.paid),yesNo(o.estimateCreated),yesNo(o.dealerDirectFinance),yesNo(o.truckScheduled),o.notes||""])
    ];
  };
  const exportInBuildXL=()=>exportCSV(buildVehicleExportRows(filteredBuilding,"Order Date"),`ready-to-ship-xl-${today()}.csv`);
  const exportShippedXL=()=>exportCSV(buildVehicleExportRows(filteredShipped,"Ship Date"),`shipped-xl-${today()}.csv`);

  return (
    <div style={{display:"flex",flexDirection:"column",gap:18}}>
      {detailOrder&&(
        <div style={{position:"fixed",inset:0,background:"rgba(10,53,132,0.5)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
          <div style={{background:"#ffffff",borderRadius:16,padding:24,maxWidth:560,width:"100%",boxShadow:"0 8px 32px rgba(10,53,132,0.2)",maxHeight:"90vh",overflowY:"auto"}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}><div style={{fontWeight:800,fontSize:16,color:"#0a3584"}}>Order Details</div><Btn small onClick={()=>setDetailOrder(null)} style={{background:"#dde3f0",color:"#6b7280"}}>✕ Close</Btn></div>
            <EditOrderForm order={detailOrder} finished={finished} showCert={detailOrder.vehicleType==="LSV"} onSave={u=>{updateOrder(u.id,u);setDetailOrder(null);showToast("Order updated ✓");}} onCancel={()=>setDetailOrder(null)}/>
          </div>
        </div>
      )}

      {groupPickModal&&(
        <div style={{position:"fixed",inset:0,background:"rgba(10,53,132,0.5)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
          <div style={{background:"#ffffff",borderRadius:16,padding:24,maxWidth:680,width:"100%",boxShadow:"0 8px 32px rgba(10,53,132,0.2)",maxHeight:"88vh",overflowY:"auto"}}>
            <div style={{fontWeight:800,fontSize:16,color:"#0a3584",marginBottom:4}}>Build Full Order</div>
            <div style={{fontSize:13,color:"#6b7280",marginBottom:16}}>Select the exact finished inventory cart to use, or choose Build from Parts. The whole order moves together.</div>
            <div style={{display:"flex",flexDirection:"column",gap:12,marginBottom:18}}>
              {groupPickModal.orders.map((o,idx)=>{
                const matches=getAvailableFinishedCarts(finished,o.model,o.body,o.seat).filter(fc=>{
                  const selectedElsewhere=Object.entries(groupBuildSelections).some(([oid,val])=>oid!==o.id&&val===fc.id);
                  return !selectedElsewhere;
                });
                const selected=groupBuildSelections[o.id] || (matches.length===0 ? "__parts" : "");
                const partsOk=canUsePartsFromMap(parts,o);
                return (
                  <div key={o.id} style={{border:"1px solid #dde3f0",borderRadius:12,padding:"12px 14px",background:"#f8fafc"}}>
                    <div style={{display:"flex",gap:10,alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",marginBottom:10}}>
                      <div>
                        <div style={{fontWeight:800,fontSize:13,color:"#0a3584"}}>Cart {idx+1}: {o.model}</div>
                        <div style={{fontSize:12,color:"#6b7280",marginTop:2}}><ColorDot color={o.body}/>{o.body} / {o.seat} · {o.customer}</div>
                      </div>
                      <span style={{fontSize:11,fontWeight:800,color:matches.length?"#10b981":partsOk?"#3b82f6":"#ef4444"}}>{matches.length?`${matches.length} inventory match(es)`:partsOk?"Parts build available":"Not buildable"}</span>
                    </div>
                    <select value={selected} onChange={e=>setGroupBuildSelections(prev=>({...prev,[o.id]:e.target.value}))} style={{width:"100%",padding:"9px 11px",borderRadius:9,border:"1px solid #cbd5e1",background:"#fff",color:"#0a3584",fontSize:13,fontWeight:700}}>
                      {matches.length>0&&<option value="">Select finished inventory cart...</option>}
                      {matches.map(fc=><option key={fc.id} value={fc.id}>Use Finished Inventory — Legacy VIN {fc.vinLegacy||"N/A"} · Added {fc.dateAdded||"—"}</option>)}
                      <option value="__parts" disabled={!partsOk}>Build from Parts{partsOk?"":" — short parts"}</option>
                    </select>
                  </div>
                );
              })}
            </div>
            <div style={{display:"flex",gap:10,justifyContent:"flex-end",flexWrap:"wrap"}}>
              <Btn onClick={()=>{setGroupPickModal(null);setGroupBuildSelections({});}} style={{background:"#dde3f0",color:"#6b7280"}}>Cancel</Btn>
              <Btn onClick={confirmGroupBuild} style={{background:"#f59e0b",color:"#fff"}}>Build Entire Order</Btn>
            </div>
          </div>
        </div>
      )}

      {/* Stats */}
      <div style={{display:"flex",gap:12,flexWrap:"wrap"}}>
        {[{label:"Open",count:new Set(open.map(o=>o.orderGroupId||o.id)).size,color:"#3b82f6"},{label:"Ready to Ship",count:new Set(building.map(o=>o.orderGroupId||o.id)).size,color:"#f59e0b"},{label:"Shipped",count:new Set(shipped.map(o=>o.orderGroupId||o.id)).size,color:"#10b981"}].map(c=>(
          <div key={c.label} style={{background:"#ffffff",borderRadius:12,padding:"12px 18px",flex:"1 1 100px",borderLeft:`4px solid ${c.color}`,boxShadow:"0 1px 6px rgba(10,53,132,0.08)"}}>
            <div style={{fontSize:22,fontWeight:800,color:c.color}}>{c.count}</div>
            <div style={{fontSize:12,color:"#6b7280"}}>{c.label}</div>
          </div>
        ))}
      </div>

      {/* Open Orders */}
      <div style={{background:"#ffffff",borderRadius:14,boxShadow:"0 1px 6px rgba(10,53,132,0.08)",overflow:"hidden"}}>
        <div style={{padding:"11px 16px",background:"#0f1829",borderBottom:"2px solid #1e3a5f",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <span style={{fontWeight:700,color:"#1d4ed8",fontSize:13}}>📋 Open Orders — {filteredOpenGroups.length}</span>
          {filteredOpenGroups.length>0&&<Btn small onClick={()=>exportOpenOrdersToExcel(orders)} style={{background:"#10b981",color:"#fff"}}>📥 Export Orders</Btn>}
        </div>
        <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:6}}>
          <Pager page={safeOpenPage} total={openTotalPages} count={filteredOpenGroups.length} onPage={setOpenPage}/>
          {openPageGroups.map(group=>{
            const groupAvail=canFillGroup(group);
            return (
              <div key={group.id} draggable onDragStart={()=>setDragOrderId(group.id)} onDragOver={e=>e.preventDefault()} onDrop={()=>moveOpenOrderInQueue(dragOrderId,group.id)} style={{border:"1px solid #dde3f0",borderRadius:10,padding:"10px 13px",background:dragOrderId===group.id?"#e0f2fe":"#f8fafc",display:"flex",flexDirection:"column",gap:8,cursor:"grab"}}>
                <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}>
                  <div style={{fontSize:18,color:"#94a3b8",cursor:"grab",lineHeight:1}}>⋮⋮</div>
                  <div style={{flex:"1 1 220px"}}>
                    <div style={{fontWeight:800,fontSize:13,color:"#0a3584"}}>#{group.position===999999?"—":group.position} · {group.dealer} · {group.orders.length} cart(s)</div>
                    <div style={{fontSize:12,color:"#6b7280",marginTop:3}}>Order: {group.id}</div>
                  </div>
                  <span style={{fontSize:11,fontWeight:700,color:groupAvail?"#10b981":"#ef4444"}}>{groupAvail?"✓ Fillable":"✗ Short / TBD"}</span>
                  {groupAvail&&<Btn small onClick={()=>openGroupBuildPicker(group)} style={{background:"#f59e0b",color:"#fff"}}>▶ Build Order</Btn>}
                </div>
                {group.orders.map(o=>{
                  const avail=(o.seat!=="TBD"&&o.body!=="TBD")?calcTotalAvailable(o.model,o.body,o.seat):null;
                  return <div key={o.id} style={{border:"1px solid #dde3f0",borderRadius:8,padding:"8px 10px",background:"#fff",display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginLeft:28}}>
                    <div style={{flex:"1 1 220px"}}>
                      <div style={{fontWeight:700,fontSize:13,color:"#0a3584"}}>{o.model}</div>
                      <div style={{fontSize:12,color:"#6b7280",marginTop:3,display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}><ColorDot color={o.body}/><span style={{fontWeight:600,color:o.body==="TBD"?"#f59e0b":"#334155"}}>{o.body}</span><span>·</span><span style={{fontWeight:600,color:o.seat==="TBD"?"#f59e0b":"#334155"}}>{o.seat}</span><span>·</span><span>{o.date}</span>{o.customization&&<><span>·</span><span>{o.customization}</span></>}{o.notes&&<><span>·</span><span style={{color:"#f59e0b"}}>{o.notes}</span></>}</div>
                    </div>
                    <span style={{fontSize:11,fontWeight:700,color:avail===null?"#f59e0b":avail>0?"#10b981":"#ef4444"}}>{avail===null?"TBD":avail>0?`✓ ${avail} avail`:"✗ Short"}</span>
                    <Btn small onClick={()=>openDetail(o)} style={{background:"#dde3f0",color:"#6b7280"}}>✏️ Edit</Btn>
                  </div>;
                })}
              </div>
            );
          })}
          {filteredOpen.length===0&&<div style={{textAlign:"center",padding:20,color:"#6b7280",fontSize:13}}>No open orders.</div>}
          {openTotalPages>1&&<Pager page={safeOpenPage} total={openTotalPages} count={filteredOpenGroups.length} onPage={setOpenPage} style={{marginTop:8}}/>}
        </div>
      </div>

      {/* Ready to Ship */}
      <div style={{background:"#ffffff",borderRadius:14,boxShadow:"0 1px 6px rgba(10,53,132,0.08)",overflow:"hidden"}}>
        <div style={{padding:"11px 16px",background:"#fffbeb",borderBottom:"2px solid #78350f",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <span style={{fontWeight:700,color:"#92400e",fontSize:13}}>🔧 Ready to Ship — {new Set(filteredBuilding.map(o=>o.orderGroupId||o.id)).size}</span>
          {filteredBuilding.length>0&&<div style={{display:"flex",gap:6}}><Btn small onClick={exportInBuildXL} style={{background:"#f59e0b",color:"#fff"}}><ExportIcon/></Btn></div>}
        </div>
        <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:8}}>
          {filteredBuilding.map(o=>(
            <ReadyToShipCard key={o.id} order={o} onUpdate={updates=>updateOrder(o.id,updates)} onEdit={()=>openDetail(o)} onReopen={()=>moveTo(o.id,"open","building")} onShip={()=>{if(!allChecked(o)){showToast("All checkboxes must be checked before shipping","#ef4444");return;}moveTo(o.id,"shipped","building");}} showToast={showToast}/>
          ))}
          {filteredBuilding.length===0&&<div style={{textAlign:"center",padding:20,color:"#6b7280",fontSize:13}}>No orders in build.</div>}
        </div>
      </div>

      {/* Shipped — weekly grouped */}
      <div style={{background:"#ffffff",borderRadius:14,boxShadow:"0 1px 6px rgba(10,53,132,0.08)",overflow:"hidden"}}>
        <div style={{padding:"11px 16px",background:"#f0fdf4",borderBottom:"2px solid #0d3320",display:"flex",alignItems:"center",gap:7}}>
          <IconTruck size={15} color="#065f46"/>
          <span style={{fontWeight:700,color:"#065f46",fontSize:13}}>Shipped — {filteredShipped.length}</span>
          {filteredShipped.length>0&&<div style={{display:"flex",gap:6,marginLeft:"auto"}}><Btn small onClick={exportShippedXL} style={{background:"#10b981",color:"#fff"}}><ExportIcon/></Btn></div>}
        </div>
        <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:8}}>
          {weekMapShipped.length===0&&<div style={{textAlign:"center",padding:20,color:"#6b7280",fontSize:13}}>No shipped orders.</div>}
          {weekMapShipped.map(week=>{
            const isOpen=expandedShipWeeks.has(week.key);
            return (
              <div key={week.key} style={{borderRadius:10,overflow:"hidden",border:"1px solid #0d3320"}}>
                <div onClick={()=>toggleShipWeek(week.key)} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 14px",cursor:"pointer",background:isOpen?"#d1fae5":"#f0fdf4"}}>
                  <div style={{fontWeight:700,fontSize:13,color:"#065f46"}}>{fmtWeekLabel(week.sun,week.sat)}</div>
                  <div style={{display:"flex",alignItems:"center",gap:10}}>
                    <span style={{fontSize:11,color:"#059669"}}>{week.orders.length} order{week.orders.length!==1?"s":""}</span>
                    <span style={{fontSize:11,fontWeight:700,color:"#065f46"}}>{isOpen?"▲":"▼"}</span>
                  </div>
                </div>
                {isOpen&&(
                  <div style={{background:"#fff",borderTop:"1px solid #0d3320",padding:"8px 10px",display:"flex",flexDirection:"column",gap:6}}>
                    {week.orders.map(o=>(
                      <div key={o.id} style={{border:"1px solid #0d3320",borderRadius:10,padding:"9px 13px",background:"#f0fdf4",display:"flex",flexWrap:"wrap",gap:10,alignItems:"center"}}>
                        <div style={{flex:"1 1 220px"}}>
                          <div style={{fontWeight:700,fontSize:13,color:"#0a3584"}}>
                            {o.vinNew?<span style={{color:"#6366f1"}}>{o.vinNew} — </span>:<span style={{color:"#6b7280",fontStyle:"italic",fontSize:11}}>No VIN — </span>}
                            {o.model} · <strong>{o.customer}</strong>
                          </div>
                          <div style={{fontSize:12,color:"#6b7280",marginTop:3,display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}>
                            <ColorDot color={o.body}/><span style={{fontWeight:600}}>{o.body}</span>
                            <span>·</span><span style={{fontWeight:600}}>{o.seat}</span>
                            <span>·</span><span>{o.date}</span>
                            {/* Show checkboxes locked */}
                            <span style={{background:"#d1fae5",color:"#065f46",borderRadius:5,padding:"1px 7px",fontSize:11,fontWeight:700}}>✓ Shipped</span>
                          </div>
                          {/* Locked date field */}
                          <div style={{marginTop:6,display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
                            <label style={{display:"flex",flexDirection:"column",gap:2}}>
                              <span style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Ship Date</span>
                              <input type="date" value={o.date||""} onChange={e=>updateOrder(o.id,{date:e.target.value})} style={{padding:"4px 8px",borderRadius:6,border:"1px solid #dde3f0",fontSize:12,color:"#0a3584"}}/>
                            </label>
                          </div>
                        </div>
                        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                          <Btn small onClick={()=>moveTo(o.id,"building","shipped")} style={{background:"#dde3f0",color:"#6b7280"}}>↩ Un-ship</Btn>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ─── Ready to Ship Card with checkboxes ───────────────────────────────────────
function ReadyToShipCard({order,onUpdate,onEdit,onReopen,onShip,showToast}) {
  const o=order;
  const isLSV=o.vehicleType!=="Golf Cart";


  const serialValid=(s)=>{
    if(!s) return false;
    return /^[A-Za-z]{2}\d{6}$/.test(s);
  };

  return (
    <div style={{border:"1px solid #78350f",borderRadius:12,overflow:"hidden",background:"#fffbeb"}}>
      {/* Header */}
      <div style={{padding:"10px 14px",display:"flex",flexWrap:"wrap",gap:10,alignItems:"center",borderBottom:"1px solid #f3d08a"}}>
        <div style={{flex:"1 1 220px"}}>
          <div style={{fontWeight:700,fontSize:13,color:"#0a3584"}}>
            {o.vinNew?<span style={{color:"#6366f1"}}>{o.vinNew} — </span>:<span style={{color:"#6b7280",fontStyle:"italic",fontSize:11}}>No VIN — </span>}
            {o.model} · <strong>{o.customer}</strong>
          </div>
          <div style={{fontSize:12,color:"#6b7280",marginTop:3,display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}>
            <ColorDot color={o.body}/><span style={{fontWeight:600}}>{o.body}</span>
            <span>·</span><span style={{fontWeight:600}}>{o.seat}</span>
            <span>·</span><span>{o.date}</span>
            {o.buildSource==="finished"&&<span style={{background:"#d1fae5",color:"#065f46",borderRadius:5,padding:"1px 7px",fontSize:11,fontWeight:700}}>🏭 Finished Cart</span>}
            {o.buildSource==="parts"&&<span style={{background:"#ccd8f0",color:"#1d4ed8",borderRadius:5,padding:"1px 7px",fontSize:11,fontWeight:700}}>🔧 Parts Build</span>}
          </div>
        </div>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          <Btn small onClick={onEdit} style={{background:"#dde3f0",color:"#6b7280"}}>✏️ Edit</Btn>
          <Btn small onClick={onReopen} style={{background:"#dde3f0",color:"#6b7280"}}>↩ Reopen</Btn>
          <Btn small onClick={onShip} style={{background:"#10b981",color:"#fff"}}>🚚 Ship</Btn>
        </div>
      </div>

      {/* Checkboxes & fields */}
      <div style={{padding:"12px 16px",display:"flex",flexWrap:"wrap",gap:16}}>
        {/* Vehicle Type */}
        <div>
          <div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",marginBottom:6}}>Vehicle Type</div>
          <select value={o.vehicleType||"LSV"} onChange={e=>onUpdate({vehicleType:e.target.value,serialNumber:"",certSent:false})} style={{padding:"6px 10px",borderRadius:7,border:"1px solid #dde3f0",fontSize:12,color:"#0a3584",background:"#fff"}}>
            <option value="LSV">LSV</option>
            <option value="Golf Cart">Golf Cart</option>
          </select>
        </div>

        {/* LSV VIN fields + Cert Sent */}
        {isLSV&&(
          <>
            <div>
              <VinNewInput label="New VIN (Last 4)" value={o.vinNew||""} mode={o.vinNewMode||"typed"} onValueChange={v=>onUpdate({vinNew:v})} onModeChange={m=>onUpdate({vinNewMode:m})}/>
            </div>
            <div>
              <VinLegacyInput label="Legacy VIN (Last 4)" value={o.vinLegacy||""} onChange={v=>onUpdate({vinLegacy:v})}/>
            </div>
            <div style={{display:"flex",flexDirection:"column",gap:6,justifyContent:"flex-end"}}>
              <CheckField label="Certificate Sent" checked={o.certSent||false} onChange={v=>onUpdate({certSent:v})}/>
            </div>
          </>
        )}

        {/* Golf Cart Serial # */}
        {!isLSV&&(
          <div>
            <label style={{display:"flex",flexDirection:"column",gap:3}}>
              <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Serial # (2 letters + 6 digits)</span>
              <input
                type="text"
                maxLength={8}
                placeholder="AB123456"
                value={o.serialNumber||""}
                onChange={e=>{
                  const raw=e.target.value.toUpperCase();
                  // Allow 2 alpha + 6 numeric
                  let filtered="";
                  if(raw.length<=2) filtered=raw.replace(/[^A-Z]/g,"");
                  else filtered=raw.slice(0,2).replace(/[^A-Z]/g,"")+raw.slice(2).replace(/[^0-9]/g,"").slice(0,6);
                  onUpdate({serialNumber:filtered});
                }}
                style={{padding:"7px 10px",borderRadius:8,border:`1px solid ${o.serialNumber&&!serialValid(o.serialNumber)?"#fca5a5":"#dde3f0"}`,fontSize:13,color:"#0a3584",background:"#ffffff",width:130,fontFamily:"monospace"}}
              />
              {o.serialNumber&&!serialValid(o.serialNumber)&&<span style={{fontSize:11,color:"#ef4444"}}>Format: 2 letters + 6 digits</span>}
            </label>
          </div>
        )}

        {/* Optional order amount for dashboard YTD totals */}
        <div>
          <label style={{display:"flex",flexDirection:"column",gap:3}}>
            <span style={{fontSize:11,fontWeight:700,color:"#6b7280",textTransform:"uppercase"}}>Order $ Amount</span>
            <input type="text" inputMode="decimal" placeholder="0.00" value={o.orderAmount??""} onChange={e=>{const v=e.target.value.replace(/[^0-9.]/g,"");onUpdate({orderAmount:v});}} style={{padding:"7px 10px",borderRadius:8,border:"1px solid #dde3f0",fontSize:13,color:"#0a3584",background:"#ffffff",width:120}}/>
          </label>
        </div>

        {/* Universal checkboxes */}
        <div style={{display:"flex",gap:12,flexWrap:"wrap",alignItems:"flex-end"}}>
          <CheckField label="Ship Quote" checked={o.shipQuote||false} onChange={v=>onUpdate({shipQuote:v})}/>
          <CheckField label="Paid" checked={o.paid||false} onChange={v=>onUpdate({paid:v})}/>
          <CheckField label="Estimate / Invoice Created" checked={o.estimateCreated||false} onChange={v=>onUpdate({estimateCreated:v})}/>
          <CheckField label="Dealer Direct Finance" checked={o.dealerDirectFinance||false} onChange={v=>onUpdate({dealerDirectFinance:v})}/>
        </div>
      </div>
    </div>
  );
}
